TN.defSec("gynecology-obstetrics",{"abnormal-uterine-bleeding":{"id":"abnormal-uterine-bleeding","variants":[{"id":"aub-stable","o":{"I":[{"t":"Pelvic ultrasonography may be deferred for outpatient evaluation in stable, nonpregnant patients"}],"L":[{"t":"Pregnancy test (all women of reproductive age); PT/INR if coagulopathy suspected; thyroid function tests if symptoms and signs of thyroid dysfunction"}],"T":[{"t":"Oral contraceptive: Ethinyl estradiol 35 μg and Norethindrone 1 mg (Ortho-Novum 1/35) three tablets daily for 7 days; or taper: four tablets for 2 days, three tablets for 2 days, two tablets for 2 days, one tablet for 3 days"},{"t":"Or Medroxyprogesterone 20 mg three times per day for 7 days, or 10 mg per day for 10 days"},{"t":"Or Tranexamic acid 600 to 1300 mg every 8 hours for 3 days"},{"t":"Naproxen 500 mg twice daily PO or Ibuprofen 400 mg every 6 hours PO","fl":[{"k":"renal","v":"avoid in renal impairment"}]}],"Co":[{"t":"Gynecologic consultation if hormonal therapy is considered; follow-up with gynecologic provider; defer hormonal therapy if any concern for malignancy"}]},"name":"Abnormal uterine bleeding, stable","level":"III","imp":"Abnormal uterine bleeding (AUB)","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"دختری ۲۰ ساله با خونریزی قاعدگی طولانی و نامنظم؛ علائم حیاتی پایدار؛ تست حاملگی منفی.","why":"اغلب پایدار و بدون نیاز به اقدام حاد؛ درمان هورمونی کوتاه‌مدت و پیگیری زنان."},{"id":"aub-unstable","o":{"L":[{"t":"Pregnancy test; CBC (signs of excessive bleeding or anemia); PT/INR"}],"S":[{"t":"Aggressive IV crystalloids; blood products"}],"T":[{"t":"Conjugated estrogen (Premarin) 25 mg IV every 2 to 6 hours until bleeding slows, followed by an oral contraceptive"}],"Co":[{"t":"Gynecologic consultation for urgent dilation and curettage; admit to gynecologic service"}]},"name":"Abnormal uterine bleeding with hemodynamic instability","level":"I","imp":"Abnormal uterine bleeding with hemorrhage","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۳۵ ساله با خونریزی شدید رحمی، ضعف، تاکی‌کاردی و فشار 80/50.","why":"خونریزی ناپایدار: احیا، استروژن وریدی با دوز بالا و آماده‌سازی D&C."}],"ch":"58","name":"Abnormal vaginal bleeding in the nonpregnant patient (AUB)","name_fa":"خونریزی غیرطبیعی رحمی در بیمار غیرحامله (AUB)","cc":["vaginal-bleeding"],"keywords":"abnormal uterine bleeding, AUB, dysfunctional uterine bleeding, anovulatory, conjugated estrogen, tranexamic acid, medroxyprogesterone, von Willebrand, خونریزی رحمی","status":"draft","features":["تعیین وضعیت حاملگی در سن باروری حیاتی است؛ تست حاملگی برای همه زنان سن باروری","شرح حال: مقدار و مدت خونریزی، تاریخچه تولیدمثلی/جنسی، STI، تروما، دارو، جسم خارجی، علائم اختلال خونریزی (کبودی، اپیستاکسی)، اختلال اندوکرین یا بیماری کبد؛ معاینه کامل شکم و لگن با اسپکولوم و دوهمی در بیماران غیر باکره","رنگ‌پریدگی پوست/ملتحمه، علائم حیاتی غیرطبیعی، سرگیجه، سنکوپ یا ضعف: خونریزی قابل‌توجه","پیش از بلوغ: تروما/سوءاستفاده جنسی، واژینیت، تومور، جسم خارجی؛ خونریزی با ترشح: جسم خارجی؛ تا 20٪ نوجوانان با AUB اختلال انعقادی اولیه (vWD) دارند","سن باروری/پری‌منوپوز: آنوولاسیون، حاملگی، هورمون خارجی، کواگولوپاتی، لیومیوم، پولیپ سرویکس/اندومتر، عفونت لگنی، اختلال تیروئید","یائسگی: استروژن خارجی، واژینیت آتروفیک، ضایعات اندومتر شامل سرطان و تومورها","AUB: اصطلاح جدید؛ ساختاری و غیرساختاری؛ DUB دیگر توصیه نمی‌شود؛ آنوولاتوری: قاعدگی طولانی، نامنظم، بین‌قاعدگی؛ معمولاً بدون درد و کم؛ گاهی شدید با آنمی و کمبود آهن"],"ddx":[{"n":"Ectopic pregnancy / threatened or incomplete abortion |","cm":1},{"n":"Endometrial or cervical malignancy (postmenopausal) |","cm":1},{"n":"Anovulatory bleeding |"},{"n":"Coagulopathy / von Willebrand disease |"},{"n":"Leiomyoma / polyps |"},{"n":"Pelvic infection / thyroid dysfunction |"}],"redflags":["ناپایداری همودینامیک یا خونریزی ادامه‌دار، شک به بدخیمی (هورمون‌تراپی را به تعویق بینداز)"],"guide":"بیشتر بیماران پایدارند و اقدام حاد نمی‌خواهند. ناپایدار با خونریزی ادامه‌دار: احیای تهاجمی با کریستالوئید، فرآورده خونی و مشاوره زنان برای D&C فوری.\n1. ناپایدار با خونریزی شدید: استروژن وریدی با دوز بالا خط اول: conjugated estrogen (Premarin) 25 mg IV هر 2 تا 6 ساعت تا کاهش خونریزی، سپس قرص ضدبارداری؛ بستری زنان.\n2. پایدار: هورمون‌تراپی کوتاه‌مدت: (الف) قرص ضدبارداری: ethinyl estradiol 35 μg + norethindrone 1 mg (Ortho-Novum 1/35) سه قرص روزانه 7 روز، یا تدریجی: چهار قرص 2 روز، سه قرص 2 روز، دو قرص 2 روز، یک قرص 3 روز؛ (ب) medroxyprogesterone 20 mg سه بار روزانه 7 روز یا 10 mg روزانه 10 روز؛ (ج) tranexamic acid (Lysteda) 600 تا 1300 mg هر 8 ساعت 3 روز. خونریزی قطع هورمون 3 تا 10 روز بعد ممکن است شدید باشد؛ مشاوره زنان.\n3. شک به بدخیمی: هورمون‌تراپی را به بعد از ارزیابی زنان و تصمیم بیوپسی موکول کن.\n4. NSAID (naproxen 500 mg دو بار روزانه یا ibuprofen 400 mg هر 6 ساعت) ممکن است خونریزی را کم کند.\n5. پایدار: ترخیص و پیگیری زنان. سونوگرافی ممکن است برای سرپایی به تعویق بیفتد.","pearls":["تست حاملگی در همه زنان سن باروری، قبل از هر چیز."],"section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 58: Vaginal Bleeding and Pelvic Pain in the Nonpregnant Patient Joelle Borhart, pp. 319–322"},"pelvic-pain-nonpregnant":{"id":"pelvic-pain-nonpregnant","variants":[{"id":"pelvic-pain-stable","o":{"I":[{"t":"Pelvic ultrasound guided by history and physical examination (confirmatory for leiomyomas)"}],"L":[{"t":"Pregnancy test; urinalysis; CBC guided by history and physical examination"}],"T":[{"t":"NSAIDs for pain control; Oxycodone/acetaminophen (5/325) one to two tablets every 4 to 6 hours PO for a few days if needed","fl":[{"k":"hi","v":""}]}],"Co":[{"t":"Gynecologic follow-up; reevaluation in 12 to 24 hours if any concern persists"}]},"name":"Pelvic pain, stable (cyst, endometriosis, fibroid, undifferentiated)","level":"III","imp":"Pelvic pain (ovarian cyst / endometriosis / leiomyoma)","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۲۸ ساله با درد لگن یک‌طرفه خفیف تا متوسط، پایدار؛ تست حاملگی منفی.","why":"اغلب ترخیص با ضددرد و پیگیری زنان؛ سونوگرافی بر اساس بالین."},{"id":"pelvic-pain-torsion","o":{"I":[{"t":"Ultrasound with Doppler flow imaging (diagnostic procedure of choice, not 100% sensitive)"}],"L":[{"t":"Pregnancy test"}],"T":[{"t":"Analgesia","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Gynecologic consultation and preparation for surgery"}]},"name":"Suspected ovarian torsion","level":"I","imp":"Ovarian torsion","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۲۵ ساله با درد شدید ناگهانی آدنکس راست پس از ورزش، تهوع؛ کیست بزرگ در سابقه.","why":"اورژانس جراحی؛ حفظ تخمدان نیازمند مداخله سریع."}],"ch":"58","name":"Pelvic pain in the nonpregnant patient (ovarian cyst, ovarian torsion, endometriosis, leiomyoma)","name_fa":"درد لگنی در بیمار غیرحامله (کیست تخمدان، پیچ‌خوردگی تخمدان، اندومتریوز، لیومیوم)","cc":["abdominal-pain"],"keywords":"pelvic pain, ovarian cyst, ovarian torsion, endometriosis, leiomyoma, fibroid, Doppler, hemorrhagic cyst, درد لگن","status":"draft","features":["منشأ ژنیکولوژیک؛ درد ارجاعی از IBD، UTI/سنگ، دیورتیکولیت، AAA نشت‌کننده، آپاندیسیت؛ حاملگی را در سن باروری رد کن؛ PID شایع است (فصل ۶۴)","شروع ناگهانی یک‌طرفه: کیست تخمدان، torsion، انسداد یا سنگ کلیه؛ تدریجی: عفونت یا توده در حال رشد","کیست علامت‌دار: درد ناگهانی یک‌طرفه؛ خونریزی کیست (هموراژیک) یا پارگی (علائم حیاتی غیرطبیعی و شکم حاد)؛ > 8 cm، چندحفره‌ای یا جامد: نگرانی برای بدخیمی، درموئید یا اندومتریوما؛ در یائسگی توده تخمدان تا اثبات خلاف بدخیم است","torsion تخمدان: درد ناگهانی شدید آدنکس از ایسکمی؛ اورژانس جراحی؛ پس از فعالیت؛ عوامل خطر: حاملگی (کورپوس لوتئوم بزرگ)، کیست/تومور بزرگ، القای تخمک‌گذاری (OHSS)؛ تظاهر آتیپیک شایع","سونوگرافی با دوپلر روش انتخابی ولی 100٪ حساس نیست؛ اوایل ممکن است جریان شریانی حفظ باشد یا در دتورسیون موقت طبیعی باشد","اندومتریوز: درد لگنی راجعه مرتبط با قاعدگی، دیسپارونی و ناباروری؛ تشخیص قطعی در ED نیست","لیومیوم: تومور خوش‌خیم عضله صاف؛ 30٪ علامت‌دار (خونریزی، دیسمنوره، نفخ، کمردرد، ادراری، دیسپارونی)؛ پیچ‌خوردگی فیبروم پدونکوله یا انفارکتوس درد شدید می‌دهد؛ سونوگرافی تأییدی"],"ddx":[{"n":"Ovarian torsion |","cm":1},{"n":"Ectopic pregnancy |","cm":1},{"n":"Appendicitis / leaking aortic aneurysm |","cm":1},{"n":"Ruptured or hemorrhagic ovarian cyst |"},{"n":"Pelvic inflammatory disease |"},{"n":"Renal stone / diverticulitis / inflammatory bowel disease |"}],"redflags":["شروع ناگهانی درد شدید یک‌طرفه (torsion)، علائم حیاتی غیرطبیعی یا شکم حاد (پارگی کیست)، توده بزرگ یا جامد"],"guide":"معاینه کامل شکم و لگن با اسپکولوم و دوهمی؛ تست حاملگی؛ UA، CBC و سونوگرافی بر اساس بالین. بیشتر بیماران ترخیص می‌شوند حتی بدون تشخیص اختصاصی؛ ترخیص با تشخیص «درد شکم تمایزنیافته» مناسب است؛ دستورالعمل ترخیص دقیق با هشدارهای بازگشت؛ بازارزیابی در 12 تا 24 ساعت در صورت نگرانی. NSAID برای بیشتر کافی است؛ گاهی اپیوئید: oxycodone/acetaminophen (5/325) یک تا دو قرص هر 4 تا 6 ساعت PO چند روز. torsion مشکوک: ضددرد، مشاوره زنان و آماده‌سازی عمل. اندومتریوز: ضددرد و ارجاع. لیومیوم: NSAID، هورمونی برای خونریزی، ارجاع زنان.","pearls":["دوپلر طبیعی torsion را رد نمی‌کند."],"section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 58: Vaginal Bleeding and Pelvic Pain in the Nonpregnant Patient Joelle Borhart, pp. 319–322"},"ectopic-pregnancy":{"id":"ectopic-pregnancy","variants":[{"id":"ectopic-unstable","o":{"I":[{"t":"Bedside ultrasound (intrauterine pregnancy vs free fluid)"}],"L":[{"t":"Bedside urine pregnancy test; blood type and Rh factor with cross-match; quantitative β-hCG if indicated; serum electrolytes as required"}],"S":[{"t":"Two large-bore IV lines with rapid infusion of crystalloid and/or packed red blood cells to maintain blood pressure"}],"T":[{"t":"Anti-Rho(D) immunoglobulin 50 μg","if":"Rh-negative"}],"Co":[{"t":"Notify the obstetric-gynecologic consultant immediately (before laboratory and diagnostic tests are complete); laparoscopy"}]},"name":"Suspected ruptured ectopic pregnancy (unstable)","level":"I","imp":"Ruptured ectopic pregnancy","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۲۹ ساله با درد شکم شدید، آمنوره 7 هفته، فشار 80/50 و تاکی‌کاردی.","why":"EP پاره‌شده: دو IV بزرگ، مایع/PRBC و اطلاع فوری به زنان حتی قبل از تکمیل آزمایش."},{"id":"ectopic-stable","o":{"I":[{"t":"Transabdominal ultrasound first; transvaginal if not diagnostic (goal: determine whether an intrauterine pregnancy is present)"}],"L":[{"t":"Bedside urine pregnancy test; quantitative serum β-hCG (repeat in 2 days; should increase at least 66%); blood type and Rh factor"}],"T":[{"t":"Anti-Rho(D) immunoglobulin 50 μg","if":"Rh-negative"}],"Co":[{"t":"Obstetric-gynecologic consultant (close communication essential); stable reliable patient with indeterminate ultrasound and β-hCG below 1000 mIU/mL: discharge with ectopic precautions and follow-up in 2 days for repeat β-hCG and reevaluation"}]},"name":"Suspected ectopic pregnancy, stable (indeterminate ultrasound)","level":"II","imp":"Possible ectopic pregnancy","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"زنی ۲۶ ساله با لکه‌بینی و درد خفیف زیر شکم، آمنوره 5 هفته، پایدار؛ سونوگرافی نامشخص و β-hCG 800.","why":"بیمار پایدار با β-hCG پایین می‌تواند با هشدار EP و پیگیری 2 روزه ترخیص شود."}],"ch":"59","name":"Ectopic pregnancy","name_fa":"حاملگی نابجا","cc":["pregnancy","vaginal-bleeding","abdominal-pain"],"keywords":"ectopic pregnancy, beta-hCG, discriminatory zone, methotrexate, Rho(D) immunoglobulin, hemoperitoneum, heterotopic, حاملگی نابجا","status":"draft","features":["علت اصلی مرگ مادری در سه‌ماهه اول؛ عوامل خطر: PID، جراحی لوله (بستن)، EP قبلی، DES، IUD، تکنیک‌های کمک‌باروری","محل: غالباً لوله فالوپ (آمپولا)؛ سرویکس، شکم، اسکار سزارین","تریاد (درد، خونریزی، آمنوره) ممکن است نباشد؛ 90٪ درد شکم؛ 50٪ تا 80٪ خونریزی؛ 70٪ آمنوره","درد ناگهانی، یک‌طرفه، شدید یا خفیف و منتشر؛ هموپریتوان: درد ارجاعی به شانه یا شکم فوقانی","علائم حیاتی ممکن است حتی در EP پاره‌شده طبیعی باشد؛ برادی‌کاردی نسبی (واگ)؛ همبستگی ضعیف بین حجم هموپریتوان و علائم حیاتی","معاینه: CMT، تندرنس آدنکس ± توده، رحم بزرگ؛ تون جنین ممکن است بعد از 12 هفته","تست ادرار β-hCG: آستانه > 20 mIU/mL؛ حساسیت/ویژگی 95٪ تا 100٪؛ ادرار رقیق (< 50) منفی کاذب؛ سرم کمی: حساسیت تقریباً 100٪ برای > 5 mIU/mL","سونوگرافی: هدف اثبات IUP؛ رد EP نمی‌کند؛ IUP قطعی EP را عملاً رد می‌کند (مگر heterotopic)؛ رحم خالی بی‌توده و مایع: نامشخص؛ β-hCG > 6000 (ترانس‌ابدومینال) یا > 1500 (ترانس‌واژینال) با رحم خالی: مطرح EP؛ β-hCG پایین: تکرار در 2 روز (افزایش حداقل 66٪)"],"ddx":[{"n":"Ruptured ectopic pregnancy |","cm":1},{"n":"Threatened / incomplete / missed abortion |"},{"n":"Heterotopic pregnancy / molar pregnancy |"},{"n":"Implantation bleeding / corpus luteum cyst |"},{"n":"Ovarian torsion / appendicitis / PID |"}],"redflags":["پاره‌شدن با شوک (علائم حیاتی ممکن است طبیعی باشد)، درد شانه، پریتونیت"],"guide":"در هر زن سن باروری با درد شکم و/یا خونریزی واژینال به EP فکر کن. بیمار ناپایدار: دو IV بزرگ، انفوزیون سریع کریستالوئید و/یا PRBC؛ تست حاملگی کنار تخت؛ فوراً به زنان اطلاع بده. خون: گروه و Rh (کراس‌مچ در ناپایدار)، β-hCG کمی، الکترولیت. Rh منفی: anti-Rho(D) immunoglobulin 50 μg. پایدار قابل‌اعتماد با سونوگرافی نامشخص و β-hCG < 1000: ترخیص با هشدار EP و پیگیری 2 روز. درمان قطعی توسط زنان: لاپاروسکوپی، D&C یا متوترکسات (شکست تا 36٪؛ انتخاب دقیق).","pearls":["علائم حیاتی طبیعی EP پاره‌شده را رد نمی‌کند.","β-hCG کمی نباید تصمیم سونوگرافی را تعیین کند."],"section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 59: Ectopic Pregnancy and Emergencies in The First 20 Weeks of Pregnancy, pp. 323–327"},"abortion-first-trimester":{"id":"abortion-first-trimester","variants":[{"id":"abortion-threatened-complete","o":{"I":[{"t":"Ultrasound when the patient is stable"}],"L":[{"t":"Pelvic examination; blood typing and Rh factor determination; urine pregnancy test; quantitative β-hCG; urinalysis"}],"T":[{"t":"Anti-Rho(D) immunoglobulin (doses recommended range from 50 to 300 μg)","if":"Rh-negative"},{"t":"Discharge instructions: pelvic rest (no intercourse or tampons); return for heavy bleeding, fever or pain"}],"Co":[{"t":"Close follow-up arranged; obstetric-gynecologic consultant"}]},"name":"Threatened or complete abortion, stable","level":"III","imp":"Threatened abortion","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۲۷ ساله با حاملگی ۹ هفته و لکه‌بینی؛ os بسته؛ پایدار.","why":"تهدید یا سقط کامل با پیگیری نزدیک ترخیص می‌شود."},{"id":"abortion-incomplete-gtd","o":{"I":[{"t":"Ultrasound when stable"}],"L":[{"t":"CBC, blood type and cross-match (unstable), Rh factor, urine pregnancy test, quantitative β-hCG, urinalysis; send all recovered products of conception for pathologic examination"}],"S":[{"t":"Aggressive IV crystalloid and/or packed red blood cell infusion when appropriate"}],"T":[{"t":"Supplemental oxygen; cardiac monitor; two large-bore IV lines"},{"t":"Anti-Rho(D) immunoglobulin (50 to 300 μg)","if":"Rh-negative"},{"t":"Misoprostol (medical treatment) or dilation and curettage (surgical), decided with the consulting obstetrician","fl":[{"k":"note","v":"misoprostol dose not given in the book"}]}],"Co":[{"t":"Emergent obstetric-gynecologic consultation in the unstable patient; GTD requires close follow-up until quantitative β-hCG returns to zero"}]},"name":"Incomplete abortion or gestational trophoblastic disease (symptomatic / unstable)","level":"II","imp":"Incomplete abortion / gestational trophoblastic disease","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۳۰ ساله با خونریزی شدید، دفع بافت و اتساع os در 10 هفته.","why":"نیاز به D&C یا دارو با مشاوره زنان؛ احیای حجم در ناپایدار."},{"id":"abortion-septic","o":{"L":[{"t":"Pelvic examination; blood typing; urinalysis; cultures","fl":[{"k":"note","v":"cultures not specifically stated in this chapter"}]}],"A":[{"t":"Ampicillin/sulbactam 3 g IV, or Clindamycin 600 mg plus Gentamicin 1 to 2 mg/kg IV","fl":[{"k":"renal","v":"aminoglycoside"}]}],"Co":[{"t":"Gynecologic consultation"}]},"name":"Septic abortion","level":"I","imp":"Septic abortion","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"زنی ۲۸ ساله با تب، درد لگن و ترشح بدبو پس از سقط.","why":"عفونت حین سقط: آنتی‌بیوتیک وسیع‌الطیف و مشاوره زنان."}],"ch":"59","name":"Threatened, incomplete, complete, missed and septic abortion; gestational trophoblastic disease","name_fa":"تهدید به سقط، سقط ناقص، کامل، فراموش‌شده و عفونی؛ بیماری تروفوبلاستیک","cc":["pregnancy","vaginal-bleeding"],"keywords":"threatened abortion, incomplete abortion, missed abortion, septic abortion, molar pregnancy, GTD, misoprostol, dilation and curettage, miscarriage, سقط","status":"draft","features":["20٪ تا 40٪ حاملگی‌ها خودبه‌خود سقط می‌شوند؛ حدود 75٪ قبل از هفته 8","تهدید به سقط: خونریزی در 20 هفته اول با os بسته، معاینه خوش‌خیم و بدون دفع بافت؛ os باز: سقط اجتناب‌ناپذیر","ناقص: دفع بخشی از محصولات (POC خاکستری-سفید)؛ محتمل‌تر هفته 6 تا 14؛ کامل: دفع همه بافت قبل از هفته 20 (POC را به پاتولوژی بفرست)؛ فراموش‌شده (missed): مرگ جنین < 20 هفته بدون دفع بافت تا 4 هفته","عفونی: درد لگن، تب، CMT یا تندرنس رحم، ترشح چرکی یا بدبو","افتراق: EP، خونریزی لانه‌گزینی (تشخیص رد؛ کم و بدون درد)، GTD (مول کامل/نسبی، تومور تروفوبلاستیک، کوریوکارسینوم): خونریزی، رحم بزرگ‌تر از سن، β-hCG بسیار بالا؛ مول در هایپرمزیس یا فشار بالا در حاملگی قبل از هفته 24"],"ddx":[{"n":"Ectopic pregnancy |","cm":1},{"n":"Septic abortion |","cm":1},{"n":"Gestational trophoblastic disease |"},{"n":"Implantation bleeding |"}],"redflags":["ناپایداری، تب و ترشح بدبو (سپتیک)، خونریزی شدید"],"guide":"مثل EP: بیمار علامت‌دار/ناپایدار: اکسیژن، مانیتور قلبی، دو IV بزرگ، مشاوره اورژانس زنان؛ مایع/PRBC تهاجمی. Rh منفی: anti-Rho(D) (دوز 50 تا 300 μg؛ توافق یکسان نیست). سونوگرافی وقتی پایدار. ناقص یا GTD: D&C؛ تصمیم دارو (misoprostol) یا جراحی با مشاوره زنان؛ GTD: پیگیری تا β-hCG صفر (عدم نرمال شدن: کوریوکارسینوم). عفونی: مشاوره زنان و آنتی‌بیوتیک وسیع‌الطیف: ampicillin/sulbactam 3 g IV یا clindamycin 600 mg + gentamicin 1 تا 2 mg/kg IV. تهدید یا کامل: ترخیص با پیگیری، pelvic rest (بدون مقاربت و تامپون) و بازگشت برای خونریزی شدید، تب یا درد.","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 59: Ectopic Pregnancy and Emergencies in The First 20 Weeks of Pregnancy, pp. 323–327"},"nausea-vomiting-pregnancy":{"id":"nausea-vomiting-pregnancy","variants":[{"id":"nvp-mild","o":{"L":[{"t":"Urinalysis (ketones)"}],"S":[{"t":"5% dextrose in normal saline or 5% dextrose in Lactated Ringer's solution (failure to include dextrose may result in prolonged ketosis)","fl":[{"k":"ci","v":"not for heart failure / pulmonary edema, CKD"}]}],"T":[{"t":"Metoclopramide 10 mg IV every 6 to 8 hours, or Promethazine 12 to 25 mg IV every 4 hours, or Ondansetron 4 to 8 mg IV every 4 to 8 hours"},{"t":"Doxylamine with Pyridoxine 50 mg PO every evening as maintenance"}]},"name":"Nausea and vomiting of pregnancy, responds in the ED","level":"III","imp":"Nausea and vomiting of pregnancy","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۲۴ ساله با حاملگی ۹ هفته، تهوع و استفراغ مکرر و خشکی دهان؛ پایدار.","why":"با مایع و ضدتهوع بهبود می‌یابد و ترخیص می‌شود."},{"id":"nvp-hyperemesis","o":{"L":[{"t":"Urinalysis (ketones), serum electrolytes, BUN, creatinine"}],"S":[{"t":"5% dextrose in normal saline or 5% dextrose in Lactated Ringer's solution"}],"T":[{"t":"Metoclopramide 10 mg IV every 6 to 8 hours, or Promethazine 12 to 25 mg IV every 4 hours, or Ondansetron 4 to 8 mg IV every 4 to 8 hours"},{"t":"Methylprednisolone 16 mg PO or IV every 8 hours for 3 days, tapered over 2 weeks to the lowest effective dose (in consultation with an obstetrician)"}],"Co":[{"t":"Admission (intractable vomiting, persistent ketonuria, electrolyte abnormalities, or weight loss > 10% of prepregnancy weight); obstetrician"}]},"name":"Hyperemesis gravidarum (admission criteria)","level":"II","imp":"Hyperemesis gravidarum","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۲۶ ساله با حاملگی ۱۰ هفته، کاهش وزن 12٪، کتونوری و هیپوکالمی.","why":"استفراغ مقاوم، کتونوری یا اختلال الکترولیت بستری می‌خواهد."}],"ch":"59","name":"Nausea and vomiting of pregnancy / hyperemesis gravidarum","name_fa":"تهوع و استفراغ بارداری / هایپرمزیس گراویداروم","cc":["nausea-vomiting","pregnancy"],"keywords":"hyperemesis gravidarum, nausea vomiting pregnancy, ketonuria, metoclopramide, promethazine, ondansetron, doxylamine pyridoxine, تهوع بارداری","status":"draft","features":["معمولاً در 12 هفته اول؛ 60٪ تا 80٪ زنان باردار؛ از خفیف تا هایپرمزیس","معاینه معمولاً نرمال به‌جز علائم کم‌آبی؛ درد شکم بسیار غیرمعمول است و باید تشخیص دیگری را مطرح کند","آزمایش: CBC، الکترولیت، BUN، کراتینین و UA (کتونوری)","افتراق: EP پاره‌شده، کوله‌لیتیازیس/کولسیستیت، گاستروانتریت، پانکراتیت، آپاندیسیت، هپاتیت، PUD، پیلونفریت، کبد چرب حاملگی، HELLP"],"ddx":[{"n":"Ruptured ectopic pregnancy |","cm":1},{"n":"Appendicitis / pancreatitis |","cm":1},{"n":"HELLP syndrome / fatty liver of pregnancy |"},{"n":"Gastroenteritis / cholecystitis |"},{"n":"Pyelonephritis / peptic ulcer disease / hepatitis |"}],"redflags":["درد شکم، استفراغ مقاوم، کتونوری ادامه‌دار، اختلال الکترولیت، کاهش وزن > 10٪ وزن پیش از بارداری"],"guide":"آبرسانی با D5NS یا D5 Ringer لاکتات (نبود دکستروز ممکن است کتوز را طولانی کند). ضدتهوع: metoclopramide 10 mg IV هر 6 تا 8 ساعت، promethazine 12 تا 25 mg IV هر 4 ساعت (کلاس C ولی شایع) و ondansetron 4 تا 8 mg IV هر 4 تا 8 ساعت. بهبود در ED (کتون ادرار پاک و تحمل مایع خوراکی): ترخیص با ضدتهوع؛ doxylamine با pyridoxine 50 mg PO هر شب نگهدارنده. بستری: استفراغ مقاوم، کتونوری ادامه‌دار، اختلال الکترولیت یا کاهش وزن > 10٪؛ استروئید سیستمیک (methylprednisolone 16 mg PO/IV هر 8 ساعت 3 روز، سپس کاهش در 2 هفته) با مشاوره مامایی.","pearls":["بدون دکستروز در مایع، کتوز طولانی می‌شود."],"section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 59: Ectopic Pregnancy and Emergencies in The First 20 Weeks of Pregnancy, pp. 323–327"},"diabetes-in-pregnancy":{"id":"diabetes-in-pregnancy","variants":[{"id":"dka-pregnancy","o":{"L":[{"t":"Blood glucose, ketones, blood gas, electrolytes","fl":[{"k":"note","v":"tests as for usual DKA care, see Chapter 129"}]}],"S":[{"t":"Isotonic fluid resuscitation to correct volume deficits; continuous insulin infusion; correction of electrolyte abnormalities","fl":[{"k":"ci","v":"heart failure / pulmonary edema"}]}],"T":[{"t":"Supplemental oxygen; left lateral decubitus positioning"},{"t":"Treat the underlying cause"}],"Co":[{"t":"Obstetrician (fetal monitoring); admit"}]},"name":"DKA in pregnancy","level":"I","imp":"Diabetic ketoacidosis in pregnancy","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"زنی ۲۸ ساله با دیابت نوع 1 و حاملگی ۲۴ هفته، تهوع، تنفس عمیق و قند 220.","why":"DKA در بارداری سریع‌تر و با قند پایین‌تر؛ الگوی درمان معمول به‌علاوه وضعیت جانبی چپ؛ پایش جنین."},{"id":"hypoglycemia-pregnancy","o":{"L":[{"t":"Blood glucose"}],"S":[{"t":"snack of milk and crackers","if":"mild: glucose < 70 mg/dL and able to follow commands"},{"t":"50 mL of 50% dextrose in water IV; Glucagon 1 to 2 mg IM or subcutaneous if IV access is delayed; then 5% dextrose solution IV at 50 to 100 mL/h","if":"severe: unable to follow commands"}]},"name":"Hypoglycemia in pregnancy","level":"II","imp":"Hypoglycemia in pregnancy","cond":"Emergent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زنی ۳۰ ساله باردار دیابتی، گیج و بی‌پاسخ با قند 40.","why":"شدید: دکستروز وریدی؛ خفیف: خوراکی."}],"ch":"60","name":"Diabetes in pregnancy: DKA and hypoglycemia","name_fa":"دیابت در بارداری: کتواسیدوز و هیپوگلیسمی","cc":["pregnancy","metabolic"],"keywords":"gestational diabetes, DKA in pregnancy, hypoglycemia in pregnancy, insulin requirement, glucagon, left lateral decubitus, دیابت بارداری","status":"draft","features":["دیابتی‌ها در معرض عوارض بارداری و عوارض حاد دیابت؛ دیابت بارداری: رژیم، گاهی metformin یا glyburide؛ انسولین برای برخی و تقریباً همه دیابت نوع 1 و 2","نیاز انسولین با پیشرفت بارداری: 0.7 U/kg/d سه‌ماهه اول تا 1.0 U/kg/d در ترم","DKA سریع‌تر و در قند پایین‌تر رخ می‌دهد؛ DKA را در هر دیابتیک باردار بدحال و/یا قند ≥ 180 mg/dL در نظر بگیر","هیپوگلیسمی خفیف: قند < 70 و قادر به اجرای دستور؛ شدید: قند < 70 و ناتوان از اجرای دستور"],"ddx":[{"n":"Diabetic ketoacidosis |","cm":1},{"n":"Severe hypoglycemia |","cm":1},{"n":"Hyperemesis / sepsis |"},{"n":"Preeclampsia / HELLP |"}],"redflags":["بدحالی با قند ≥ 180، کاهش سطح هوشیاری، اسیدوز"],"guide":"DKA: اکسیژن، وضعیت دکوبیتوس جانبی چپ و درمان معمول DKA: احیای مایع ایزوتونیک، انسولین مداوم، اصلاح الکترولیت و درمان علت (فصل ۱۲۹). هیپوگلیسمی خفیف: شیر و کراکر؛ شدید: 50 mL دکستروز 50٪ IV و گلوکاگون 1 تا 2 mg IM/SC اگر IV دیر در دسترس؛ سپس دکستروز 5٪ IV با 50 تا 100 mL/h.","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 60: Comorbid Diseases in Pregnancy, pp. 328–334"},"thyroid-storm-pregnancy":{"id":"thyroid-storm-pregnancy","variants":[{"id":"thyroid-storm-pregnancy","o":{"L":[{"t":"Thyroid function tests","fl":[{"k":"note","v":"not specifically stated in this chapter"}]}],"S":[{"t":"IV fluids","fl":[{"k":"ci","v":"heart failure / pulmonary edema"}]}],"T":[{"t":"Propylthiouracil (PTU) 600–1000 mg PO loading dose followed by 200–250 mg PO every 4 h (first trimester); or Methimazole 40 mg PO loading dose followed by 25 mg PO every 4 h (second and third trimesters)"},{"t":"At least 1 h later: Lugol solution 8–10 drops every 6–8 h, or Potassium iodide 5 drops PO every 6 h, or Iopanoic acid 1 g IV every 8 h","fl":[{"k":"ci","v":"no radioactive iodine"}]},{"t":"Propranolol 1–2 mg IV every 10–15 min then 40 mg PO every 6 h, or Esmolol 500 μg/kg IV bolus then 50 μg/kg/min","fl":[{"k":"ci","v":"hold if evidence of heart failure"}]},{"t":"Hydrocortisone 100 mg IV every 8 h, or Dexamethasone 2 mg IV every 6 h"},{"t":"Left lateral decubitus position; cooling blankets; Acetaminophen 650 mg PO every 4 h"}],"Co":[{"t":"Endocrinology; obstetrician; ICU"}]},"name":"Thyroid storm in pregnancy","level":"I","imp":"Thyroid storm in pregnancy","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"زنی ۳۰ ساله با حاملگی ۱۸ هفته، تب 40، تاکی‌کاردی 160 و آژیتاسیون.","why":"طوفان تیروئید: چند محور درمان همزمان با مراقبت جنین."}],"ch":"60","name":"Hyperthyroidism and thyroid storm in pregnancy","name_fa":"پرکاری تیروئید و طوفان تیروئید در بارداری","cc":["pregnancy","fever","palpitations"],"keywords":"thyroid storm, hyperthyroidism, PTU, propylthiouracil, Lugol, propranolol, esmolol, طوفان تیروئید","status":"draft","features":["پرکاری تیروئید در بارداری: خطر پره‌اکلامپسی، ناهنجاری مادرزادی و عوارض نوزادی؛ علائم ممکن است لطیف و شبیه بارداری طبیعی باشد","درمان با PTU؛ خطر راش پورپوریک و آگرانولوسیتوز","طوفان تیروئید: تب، کم‌آبی یا دکمپانساسیون قلبی (نارسایی پرتوده)؛ درمان مشابه غیرحامله"],"ddx":[{"n":"Thyroid storm |","cm":1},{"n":"Preeclampsia |","cm":1},{"n":"Sepsis |"},{"n":"Normal pregnancy changes |"}],"redflags":["تب، تاکی‌کاردی، تغییر هوشیاری، نارسایی قلبی"],"guide":"اصول (جدول 60-1): مهار آزادسازی هورمون با تیونامید (PTU ارجح و T4→T3 را نیز مهار می‌کند): PTU 600–1000 mg PO بار سپس 200–250 mg هر 4 ساعت (سه‌ماهه اول) یا methimazole 40 mg بار سپس 25 mg هر 4 ساعت (سه‌ماهه دوم و سوم)؛ مهار تولید جدید (حداقل 1 ساعت بعد): Lugol 8–10 قطره هر 6–8 ساعت یا potassium iodide 5 قطره PO هر 6 ساعت یا iopanoic acid 1 g IV هر 8 ساعت؛ ید رادیواکتیو ممنوع؛ بلوک اثر محیطی: propranolol 1–2 mg IV هر 10–15 دقیقه و سپس 40 mg PO هر 6 ساعت یا esmolol 500 μg/kg بولوس و 50 μg/kg/min (در نارسایی قلبی نگه دار)؛ جلوگیری از تبدیل T4→T3: hydrocortisone 100 mg IV هر 8 ساعت یا dexamethasone 2 mg IV هر 6 ساعت؛ حمایتی: دکوبیتوس جانبی چپ، اکسیژن، پتوی خنک‌کننده، مایع، acetaminophen 650 mg PO هر 4 ساعت.","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 60: Comorbid Diseases in Pregnancy, pp. 328–334"},"hypertension-arrhythmia-pregnancy":{"id":"hypertension-arrhythmia-pregnancy","variants":[{"id":"htn-crisis-pregnancy","o":{"L":[{"t":"Evaluation for superimposed preeclampsia","fl":[{"k":"note","v":"see Chapter 61 for laboratory evaluation"}]}],"T":[{"t":"Labetalol loading dose 20 mg IV; maintenance 20–80 mg up to 300 mg, or constant infusion 1–2 mg/min"},{"t":"Or Hydralazine loading dose 5 mg IV or IM, then 5–10 mg every 20–40 min up to 300 mg, or constant infusion 0.5–10 mg/h","fl":[{"k":"ci","v":"use with methyldopa or labetalol to prevent reflex tachycardia"}]},{"t":"Or Nifedipine 10–30 mg orally, repeated after 45 min if needed"},{"t":"Fetal well-being closely monitored","fl":[{"k":"ci","v":"avoid ACE inhibitors and ARBs in pregnancy"}]}],"Co":[{"t":"Obstetrician"}]},"name":"Hypertensive crisis in pregnancy","level":"I","imp":"Acute hypertensive crisis in pregnancy","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۳۲ ساله با حاملگی ۳۰ هفته، فشار 190/115 و سردرد.","why":"بحران فشار در بارداری با labetalol یا hydralazine؛ پایش جنین و رد پره‌اکلامپسی."},{"id":"arrhythmia-pregnancy","o":{"T":[{"t":"Supraventricular tachycardia: vagal maneuvers, β-blockers, adenosine, verapamil and diltiazem at usual dosages"},{"t":"Atrial fibrillation requiring anticoagulation: unfractionated or low-molecular-weight heparin"},{"t":"Electrical cardioversion when indicated (not harmful to the fetus)"},{"t":"Amiodarone only for resistant, life-threatening dysrhythmias","fl":[{"k":"ci","v":"fetal neurotoxicity"}]}],"Co":[{"t":"Obstetrician; cardiology"}]},"name":"Dysrhythmia in pregnancy","level":"II","imp":"Dysrhythmia in pregnancy","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"زنی ۲۸ ساله باردار با SVT و تپش قلب.","why":"درمان مشابه غیرحامله؛ amiodarone فقط موارد مقاوم تهدیدکننده؛ کاردیوورژن بی‌خطر."}],"ch":"60","name":"Hypertensive crisis and dysrhythmias in pregnancy","name_fa":"بحران هیپرتانسیون و آریتمی در بارداری","cc":["pregnancy","palpitations","headache"],"keywords":"hypertension in pregnancy, labetalol, hydralazine, nifedipine, methyldopa, supraventricular tachycardia in pregnancy, amiodarone, فشار خون بارداری","status":"draft","features":["هیپرتانسیون مزمن: فشار > 140/90 در دو نوبت قبل از هفته 20 یا ادامه بیش از 12 هفته پس از زایمان؛ ARB و ACE inhibitor در بارداری پرهیز","بحران حاد: labetalol یا hydralazine؛ پایش جنین و در نظر گرفتن پره‌اکلامپسی سوپرایمپوز","آریتمی ممکن است با بارداری و زایمان تحریک شود؛ SVT: واگال، β-blocker، adenosine، verapamil و diltiazem با دوز معمول؛ فیبریلاسیون دهلیزی نیازمند ضدانعقاد: UFH یا LMWH؛ کاردیوورژن الکتریکی برای جنین بی‌ضرر؛ amiodarone فقط در آریتمی مقاوم تهدیدکننده حیات (نوروتوکسیسیته جنین)"],"ddx":[{"n":"Preeclampsia / eclampsia |","cm":1},{"n":"Hemodynamically significant arrhythmia |","cm":1},{"n":"Chronic hypertension |"},{"n":"Placental abruption |"}],"redflags":["فشار شدید، علائم پره‌اکلامپسی، آریتمی ناپایدار"],"guide":"جدول 60-2: hydralazine بحران: بار 5 mg IV/IM سپس 5–10 mg هر 20–40 دقیقه تا 300 mg یا انفوزیون 0.5–10 mg/h (افت فشار دیررس)؛ labetalol بحران: بار 20 mg IV؛ نگهدارنده 20–80 mg تا 300 mg یا انفوزیون 1–2 mg/min (سردرد)؛ nifedipine بحران: 10–30 mg خوراکی، تکرار بعد از 45 دقیقه (سردرد، تداخل با زایمان). درمان مزمن: labetalol 200–2400 mg روزانه، nifedipine slow-release 30–120 mg، methyldopa 0.5–3 g (خواب‌آلودگی، آنزیم کبد بالا، افسردگی)، hydralazine 50–300 mg روزانه همراه methyldopa یا labetalol، HCTZ 12.5–50 mg (کم‌آبی و اختلال الکترولیت).","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 60: Comorbid Diseases in Pregnancy, pp. 328–334"},"thromboembolism-pregnancy":{"id":"thromboembolism-pregnancy","variants":[{"id":"vte-pregnancy","o":{"I":[{"t":"Ultrasound of the lower extremities (DVT); chest radiograph first if PE is suspected; V/Q scan or CT pulmonary angiography if the chest radiograph is nondiagnostic"}],"L":[{"t":"D-dimer may not be helpful (levels increase throughout pregnancy)"}],"T":[{"t":"Unfractionated heparin or low-molecular-weight heparin at usual doses","fl":[{"k":"ci","v":"warfarin is contraindicated; crosses the placenta"}]}],"Co":[{"t":"Obstetrician"}]},"name":"Suspected DVT / PE in pregnancy","level":"II","imp":"Venous thromboembolism in pregnancy","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","sc":"زنی ۳۴ ساله با حاملگی ۲۸ هفته، تنگی نفس ناگهانی و ورم یک پا.","why":"در بارداری ابتدا CXR و سونوگرافی اندام؛ UFH/LMWH؛ بدون وارفارین."}],"ch":"60","name":"Deep vein thrombosis and pulmonary embolism in pregnancy","name_fa":"ترومبوآمبولی در بارداری (DVT و PE)","cc":["dyspnea","leg-swelling","chest-pain"],"keywords":"pregnancy DVT, pulmonary embolism in pregnancy, V/Q scan, CT-PA, heparin, low molecular weight heparin, D-dimer, warfarin contraindicated, آمبولی ریه بارداری","status":"draft","features":["شایع‌ترین علت عوارض و مرگ مادری در کشورهای صنعتی؛ عوامل: سن بالا، پاریتی، چندقلویی، زایمان عملی، استراحت و چاقی","علائم ممکن است با بارداری طبیعی اشتباه شود؛ علائم مشابه غیرحامله","شروع ارزیابی DVT: سونوگرافی اندام تحتانی؛ شک PE: ابتدا CXR؛ D-dimer در بارداری ارزش ندارد (سطح در طول بارداری بالا می‌رود)؛ اگر CXR غیرتشخیصی: V/Q یا CT-PA","جدول 60-3: CXR (تابش حداقل، نامختص)؛ CT-PA (تابش بالای پستان، تابش جنین کمتر از V/Q؛ حساسیت و ویژگی بالا؛ نیاز به دور ریختن شیر ندارد)؛ V/Q (تابش پستان کم ولی جنین بیشتر از CT-PA؛ ناکارآمد در CXR غیرطبیعی، آسم، COPD؛ شیر 12 ساعت دور ریخته شود)؛ MRI/MRV (بدون تابش؛ ایمنی gadolinium برای جنین نامعلوم)"],"ddx":[{"n":"Pulmonary embolism |","cm":1},{"n":"Aortic dissection / peripartum cardiomyopathy |","cm":1},{"n":"Normal pregnancy dyspnea / edema |"},{"n":"Pneumonia |"}],"redflags":["هیپوکسی، تاکی‌کاردی، افت فشار، سنکوپ"],"guide":"درمان: UFH یا LMWH با دوز معمول؛ وارفارین ممنوع (از جفت عبور می‌کند؛ نقایص CNS و آمبریوپاتی استخوان و غضروف و هیپوپلازی بینی و اندام). فصل ۲۵.","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 60: Comorbid Diseases in Pregnancy, pp. 328–334"},"asthma-pyelonephritis-sickle-pregnancy":{"id":"asthma-pyelonephritis-sickle-pregnancy","variants":[{"id":"asthma-pregnancy","o":{"T":[{"t":"Inhaled β2-agonist"},{"t":"Systemic corticosteroids","fl":[{"k":"note","v":"dose not given for acute therapy"}]},{"t":"Aerosolized ipratropium in severely obstructed patients"},{"t":"Terbutaline sulfate 0.25 mg SC every 20 minutes","fl":[{"k":"ci","v":"avoid subcutaneous epinephrine if possible"}]},{"t":"Discharge: Prednisone 40 to 60 mg/d for 5 to 10 days plus a rescue β-agonist"}],"Co":[{"t":"Fetal monitoring; obstetrician"}]},"name":"Asthma exacerbation in pregnancy","level":"II","imp":"Asthma exacerbation in pregnancy","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","o2":"N.C 3-5 L/min or F.M 6-10 L/min if SpO2 < 95% (keep SpO2 > 95% in pregnancy)","sc":"زنی ۲۹ ساله با حاملگی ۲۶ هفته، ویز و تنگی نفس.","why":"در بارداری SpO2 باید > 95٪ بماند؛ ایزوله از اپی‌نفرین زیرجلدی؛ پایش جنین."},{"id":"pyelonephritis-pregnancy","o":{"L":[{"t":"Urinalysis and urine culture"}],"S":[{"t":"IV hydration","fl":[{"k":"ci","v":"heart failure / pulmonary edema"}]}],"A":[{"t":"Second- or third-generation cephalosporin","fl":[{"k":"ci","v":"avoid trimethoprim-sulfamethoxazole (third trimester kernicterus), fluoroquinolones and tetracyclines"},{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Admission; many providers continue antibiotic suppression for the remainder of the pregnancy"}]},"name":"Pyelonephritis in pregnancy","level":"II","imp":"Pyelonephritis in pregnancy","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زنی ۲۷ ساله با حاملگی ۲۰ هفته، تب، لرز و درد فلانک.","why":"خطر زایمان زودرس و سپسیس؛ بستری، مایع و سفالوسپورین."},{"id":"sickle-pregnancy","o":{"S":[{"t":"Aggressive hydration","fl":[{"k":"ci","v":"heart failure / pulmonary edema"}]}],"T":[{"t":"Opiates for analgesia ; avoid NSAIDs, particularly after 32 weeks gestation","fl":[{"k":"hi","v":""}]},{"t":"Identify and treat the underlying cause; fetal monitoring"},{"t":"Blood transfusion when conservative measures fail, or with severe anemia, preeclampsia, hypoxemia, acute chest syndrome, or new-onset neurological event"}],"Co":[{"t":"Obstetrician"}]},"name":"Sickle cell vaso-occlusive crisis in pregnancy","level":"II","imp":"Sickle cell vaso-occlusive crisis in pregnancy","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","sc":"زنی ۲۵ ساله سیکل‌سل با حاملگی ۲۲ هفته و درد استخوانی شدید.","why":"هیدراتاسیون، اپیوئید، پرهیز از NSAID، ترانسفوزیون در موارد شدید."}],"ch":"60","name":"Asthma, pyelonephritis and sickle cell crisis in pregnancy","name_fa":"آسم، پیلونفریت و کریز سیکل‌سل در بارداری","cc":["dyspnea","flank-pain","joint-limb-pain"],"keywords":"asthma in pregnancy, terbutaline, prednisone, pyelonephritis in pregnancy, nitrofurantoin, sickle cell vaso-occlusive crisis, آسم بارداری","status":"draft","features":["آسم: سرفه، ویز، تنگی نفس؛ درمان حاد: SpO2 > 95٪، β2-agonist استنشاقی، کورتیکواستروئید سیستمیک، پایش جنین؛ ipratropium در انسداد شدید؛ terbutaline 0.25 mg SC هر 20 دقیقه؛ epinephrine زیرجلدی در صورت امکان پرهیز؛ PEFR در بارداری تغییر نمی‌کند (هدف 380–550 L/min)","سیستیت و پیلونفریت: تظاهر و میکروب مشابه غیرحامله؛ TMP-SMX در سه‌ماهه سوم (کرن‌ایکتروس)، فلوروکینولون و تتراسایکلین پرهیز؛ پیلونفریت تهاجمی (زایمان زودرس و سپسیس)","سیکل‌سل: خطر سقط، زایمان زودرس و VOC؛ ارزیابی و درمان مشابه غیرحامله"],"ddx":[{"n":"Preterm labor / sepsis (pyelonephritis) |","cm":1},{"n":"Acute chest syndrome |","cm":1},{"n":"Pulmonary embolism / pneumonia |"},{"n":"Vaso-occlusive crisis |"}],"redflags":["هیپوکسی، تب با درد فلانک، سندرم قفسه سینه حاد یا حادثه عصبی جدید"],"guide":"آسم: ترخیص با prednisone 40 تا 60 mg/d به مدت 5 تا 10 روز و β-agonist نجات. سیستیت: nitrofurantoin 100 mg PO دو بار روزانه 3 تا 7 روز. پیلونفریت: بستری، مایع وریدی و سفالوسپورین نسل دوم یا سوم؛ اغلب سرکوب آنتی‌بیوتیک تا پایان بارداری. سیکل‌سل VOC: هیدراتاسیون تهاجمی، ضددرد، درمان علت زمینه‌ای و پایش جنین؛ اپیوئید مجاز، NSAID پرهیز به‌ویژه پس از هفته 32؛ ترانسفوزیون در شکست درمان محافظه‌کارانه، آنمی شدید، پره‌اکلامپسی، هیپوکسمی، سندرم قفسه سینه حاد یا حادثه عصبی جدید.","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 60: Comorbid Diseases in Pregnancy, pp. 328–334"},"headache-seizure-substance-pregnancy":{"id":"headache-seizure-substance-pregnancy","variants":[{"id":"headache-pregnancy","o":{"I":[{"t":"CT scan of the brain with appropriate shielding of the uterus, if indicated"}],"T":[{"t":"Migraine: Acetaminophen, antiemetics and, if necessary, narcotics","fl":[{"k":"note","v":"doses not given in the book; ergot alkaloids and triptans should not be used"}]}],"Co":[{"t":"Obstetrician (preeclampsia/eclampsia if applicable)"}]},"name":"Headache in pregnancy","level":"II","imp":"Headache in pregnancy","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زنی ۳۰ ساله باردار با سردرد شدید ناگهانی و تهوع.","why":"هشدارها را بررسی کن؛ CT با محافظ رحم؛ میگرن با acetaminophen و ضدتهوع."},{"id":"seizure-pregnancy","o":{"T":[{"t":"Supplemental oxygen; left lateral decubitus positioning (see Chapter 145)"},{"t":"Status epilepticus with prolonged maternal hypoxia and acidosis: early intubation and ventilation"}],"Co":[{"t":"Obstetrician; neurology"}]},"name":"Seizure in pregnancy","level":"I","imp":"Seizure in pregnancy","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"زنی ۲۸ ساله با صرع و حاملگی ۳۲ هفته، تشنج ادامه‌دار.","why":"اکسیژن، وضعیت جانبی چپ و درمان تهاجمی استاتوس با اینتوباسیون زودهنگام."},{"id":"substance-pregnancy","o":{"T":[{"t":"Acute opiate withdrawal: Clonidine 0.1 to 0.2 mg SL every hour as needed for symptoms, not to exceed 0.8 mg"},{"t":"Acute cocaine intoxication and severe alcohol withdrawal: treatment unchanged from nonpregnant patients"}],"Co":[{"t":"Referral to addiction specialists for methadone or buprenorphine/naloxone therapy"}]},"name":"Substance abuse in pregnancy (cocaine, opiate withdrawal, alcohol)","level":"II","imp":"Substance abuse in pregnancy","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زنی ۲۶ ساله باردار با علائم ترک اپیوئید.","why":"ترک اپیوئید با clonidine و ارجاع؛ کوکائین و الکل مثل غیرحامله."}],"ch":"60","name":"Headache, seizure disorder and substance abuse in pregnancy","name_fa":"سردرد، تشنج و سوءمصرف مواد در بارداری","cc":["headache","seizure","behavioral","poisoning"],"keywords":"headache in pregnancy, migraine, seizure in pregnancy, status epilepticus, cocaine, opiate withdrawal, clonidine, alcohol, سردرد بارداری","status":"draft","features":["سردرد: خوش‌خیم تا تهدیدکننده (خونریزی داخل جمجمه، ترومبوز ورید مرکزی، توده، عفونت، پره‌اکلامپسی/اکلامپسی)؛ هشدارها: شروع حاد، سردرد بعد از زایمان، نقص عصبی، تب، پاپیلادم یا خونریزی شبکیه","تشنج: دوره‌ها با تغییر فارماکوکینتیک ممکن است افزایش یابد؛ مدیریت مشابه غیرحامله؛ اکسیژن و وضعیت جانبی چپ؛ استاتوس با هیپوکسی/اسیدوز مادر مرگ‌ومیر بالا","کوکائین: مرگ جنین، جدا شدن جفت، زایمان زودرس، PROM، سقط، IUGR، انفارکت مغزی جنین؛ درمان مسمومیت حاد بدون تغییر","ترک حاد اپیوئید: clonidine 0.1 تا 0.2 mg SL هر ساعت در صورت نیاز حداکثر 0.8 mg؛ ارجاع برای متادون یا buprenorphine/naloxone","الکل: سقط، وزن کم هنگام تولد، زایمان زودرس و FAS؛ درمان ترک شدید مثل غیرحامله"],"ddx":[{"n":"Eclampsia / preeclampsia |","cm":1},{"n":"Intracranial hemorrhage / cerebral venous thrombosis |","cm":1},{"n":"Migraine |"},{"n":"Status epilepticus |"}],"redflags":["سردرد حاد یا پس از زایمان، نقص عصبی، تب، پاپیلادم، استاتوس"],"guide":"CT مغز در صورت لزوم با محافظ رحم. میگرن: acetaminophen، ضدتهوع و در صورت لزوم مخدر؛ ergot و triptan ممنوع. تشنج: اکسیژن، وضعیت جانبی چپ (فصل ۱۴۵)؛ استاتوس: اینتوباسیون و تهویه زودهنگام.","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 60: Comorbid Diseases in Pregnancy, pp. 328–334"},"pregnancy-drugs-imaging":{"id":"pregnancy-drugs-imaging","variants":[{"id":"drugs-imaging-reference","o":{"T":[{"t":"Review drug safety (Table 60-4) and LactMed (National Library of Medicine Drugs and Lactation Database) before prescribing","fl":[{"k":"note","v":"reference step, no order text in the book"}]}]},"name":"Medication / imaging safety review in pregnancy","level":"III","imp":"Medication or imaging safety question in pregnancy","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۳۰ ساله باردار نیازمند دارو یا تصویربرداری.","why":"مرور ایمنی دارو و تابش."}],"ch":"60","name":"Medications and diagnostic imaging in pregnancy and lactation","name_fa":"داروها و تصویربرداری در بارداری و شیردهی","cc":["pregnancy"],"keywords":"teratogenic drugs, drugs in pregnancy, LactMed, radiation in pregnancy, ACE inhibitors, warfarin, fluoroquinolones, داروهای بارداری","status":"draft","features":["داروهای شناخته‌شده با اثر سوء (جدول 60-4): ACEi/ARB (نارسایی کلیه، oligohydramnios)؛ آمینوگلیکوزید (اوتوتوکسیسیتی؛ gentamicin کلاس D)؛ استروئید آندروژنیک (مذکرسازی)؛ ضدتشنج (carbamazepine، hydantoin، valproate: سندرم دیسمورفیک، NTD)؛ ضدتیروئید (گواتر جنین)؛ آسپرین دوز بالا (خونریزی)؛ سیتوتوکسیک مثل methotrexate؛ erythromycin estolate (هپاتوتوکسیسیتی مادر)؛ فلوروکینولون (غضروف)؛ isotretinoin؛ lithium (Ebstein)؛ NSAID طولانی پس از هفته 32 (oligohydramnios و بسته‌شدن داکتوس)؛ streptomycin؛ سولفونامید (همولیز جنین، کرن‌ایکتروس نزدیک ترم)؛ تتراسایکلین (دندان و استخوان)؛ trimethoprim و methotrexate (آنتی‌فولات اول بارداری)؛ thalidomide؛ warfarin","برای داروهای فهرست‌نشده: LactMed (NLM)","تصویربرداری: آستانه تراتوژنیک تابش 10 rad؛ سه‌ماهه اول آسیب‌پذیرترین؛ هیچ تست واحدی از آستانه نمی‌گذرد ولی اثر تجمعی را در نظر بگیر؛ سونوگرافی و MRI با تراتوژنی مرتبط نیستند"],"ddx":[{"n":"Teratogenic drug exposure |","cm":1}],"redflags":["مصرف داروی ممنوع در بارداری"],"guide":"قبل از تجویز هر دارو در بارداری و شیردهی فهرست داروهای ناایمن را مرور کن؛ از سونوگرافی و MRI در صورت امکان استفاده کن؛ تابش یونیزان را فقط وقتی لازم است و با در نظر گرفتن اثر تجمعی.","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 60: Comorbid Diseases in Pregnancy, pp. 328–334"},"preeclampsia-eclampsia":{"id":"preeclampsia-eclampsia","variants":[{"id":"preeclampsia-mild","o":{"L":[{"t":"Urinalysis for protein; platelet count, liver enzymes, creatinine, LDH"}],"Co":[{"t":"Obstetrician consultation; arrangements for frequent laboratory evaluation and close fetal surveillance (hospitalize any patient with sustained BP ≥ 140/90 plus symptoms of preeclampsia)"}]},"name":"Mild preeclampsia (outpatient candidate)","level":"III","imp":"Mild preeclampsia","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زنی ۳۰ ساله با حاملگی ۳۶ هفته، فشار 145/95، پروتئینوری و بدون علامت.","why":"با مشاوره مامایی ممکن است سرپایی با آزمایش مکرر و پایش جنین."},{"id":"preeclampsia-severe-eclampsia","o":{"I":[{"t":"Focused ultrasonography or CT of the pelvis and abdomen if subcapsular hematoma is a concern"}],"L":[{"t":"CBC with platelets, peripheral smear (schistocytes), creatinine, AST, ALT, LDH, urinalysis"}],"T":[{"t":"Magnesium sulfate loading dose 4 to 6 g IV over 20 minutes, followed by maintenance infusion 1 to 2 g/h; monitor serum magnesium levels and reflexes","fl":[{"k":"renal","v":"adjust in renal insufficiency"}]},{"t":"Severe hypertension > 160/110: Labetalol 20 mg IV initial bolus, then repeat boluses 40 to 80 mg if needed to a maximum of 300 mg; or Hydralazine 5.0 mg IV initially, then 5 to 10 mg every 10 minutes"}],"Co":[{"t":"Emergent obstetrician consultation; definitive treatment requires delivery of the fetus"}]},"name":"Severe preeclampsia / eclampsia / HELLP","level":"I","imp":"Severe preeclampsia / eclampsia / HELLP syndrome","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"زنی ۲۸ ساله با حاملگی ۳۴ هفته، فشار 185/115، سردرد شدید و تشنج.","why":"منیزیم برای پیشگیری از تشنج، کنترل فشار و زایمان؛ مشاوره فوری مامایی."}],"ch":"61","name":"Preeclampsia, eclampsia and HELLP syndrome","name_fa":"پره‌اکلامپسی، اکلامپسی و سندرم HELLP","cc":["pregnancy","headache","seizure","hypotension-shock"],"keywords":"preeclampsia, eclampsia, HELLP, magnesium sulfate, labetalol, hydralazine, gestational hypertension, پره‌اکلامپسی, اکلامپسی","status":"draft","features":["هیپرتانسیون مزمن: ≥ 140/90 قبل از بارداری، قبل از هفته 20 یا بیش از 12 هفته بعد از زایمان؛ خطر جدا شدن جفت، پره‌اکلامپسی، وزن کم تولد، سزارین، زایمان زودرس، مرگ جنین","هیپرتانسیون بارداری: ≥ 140/90 بعد از هفته 20 یا بلافاصله پس از زایمان بدون پروتئینوری؛ فشار ≥ 140/90 دو بار با فاصله ≥ 4 ساعت","پره‌اکلامپسی: هیپرتانسیون + پروتئینوری ≥ 300 mg/24h از هفته 20 تا 4–6 هفته بعد از زایمان؛ بدون پروتئینوری: ترومبوسیتوپنی < 100000، آنزیم کبدی دو برابر، کراتینین 1.1 یا دو برابر، ادم ریه، تغییر هوشیاری یا اختلال بینایی؛ ادم ممکن است نباشد","شدید: سردرد، اختلال بینایی، تغییر هوشیاری، ادم، الیگوری، تنگی نفس (ادم ریه)، درد شکم؛ فشار معمولاً ≥ 160/110","HELLP: همولیز، آنزیم کبدی بالا و پلاکت پایین؛ درد اپی‌گاستر و RUQ؛ فشار همیشه بالا نیست؛ در هر زن > 20 هفته با درد شکم مدنظر باشد","اکلامپسی: پره‌اکلامپسی همراه تشنج","تشخیص بالینی؛ آزمایش در شدید: کم‌خونی، ترومبوسیتوپنی، کراتینین بالا، آنزیم کبدی و LDH بالا؛ HELLP: شیستوسیت، پلاکت < 150000/mL، AST/ALT بالا","هماتوم ساب‌کپسولار کبد (سونو یا CT) با پارگی مرگ‌ومیر بالا"],"ddx":[{"n":"HELLP syndrome / subcapsular liver hematoma |","cm":1},{"n":"Eclampsia (seizure) |","cm":1},{"n":"Worsening chronic hypertension / transient hypertension |"},{"n":"Renal disease / fatty liver of pregnancy |"},{"n":"Coagulation disorders |"}],"redflags":["فشار ≥ 160/110، سردرد/اختلال بینایی، تشنج، درد RUQ/اپی‌گاستر، پلاکت پایین"],"guide":"1. پره‌اکلامپسی شدید و اکلامپسی: magnesium sulfate بار 4 تا 6 g IV طی 20 دقیقه، سپس انفوزیون 1 تا 2 g/h برای پیشگیری از تشنج؛ پایش سطح منیزیم و رفلکس‌ها.\n2. فشار > 160/110: labetalol 20 mg IV بولوس اولیه، سپس 40 تا 80 mg تکراری تا حداکثر 300 mg یا hydralazine 5.0 mg IV سپس 5 تا 10 mg هر 10 دقیقه.\n3. مشاوره اورژانس مامایی؛ 4. بستری همه با فشار پایدار ≥ 140 یا ≥ 90 با علائم پره‌اکلامپسی؛ 5. درمان قطعی: زایمان جنین؛ 6. خفیف: ممکن است سرپایی پس از مشاوره مامایی با آزمایش مکرر و پایش نزدیک جنین.","pearls":["هر زن باردار > 20 هفته با درد شکم: HELLP را در نظر بگیر حتی با فشار طبیعی."],"section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 61: Emergencies After 20 Weeks of Pregnancy and The Postpartum Period, pp. 335–339"},"chest-pain-pregnancy":{"id":"chest-pain-pregnancy","variants":[{"id":"chest-pain-mi-pregnancy","o":{"L":[{"t":"Cardiac troponin","fl":[{"k":"note","v":"not specified in this chapter"}]}],"T":[{"t":"Aspirin and heparin; percutaneous intervention rather than thrombolytics"},{"t":"Heart failure and pulmonary edema: standard modalities","fl":[{"k":"ci","v":"avoid sodium nitroprusside (thiocyanate and cyanide accumulation in the fetus)"}]}],"Co":[{"t":"Cardiology and obstetrician"}]},"name":"Acute myocardial infarction or pulmonary edema in pregnancy","level":"I","imp":"Acute myocardial infarction / heart failure in pregnancy","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"زنی ۳۸ ساله با حاملگی ۳۲ هفته، درد قفسه سینه و ST elevation.","why":"در بارداری PCI به‌جای ترومبولیتیک؛ نیتروپروساید ممنوع."}],"ch":"61","name":"Chest pain, MI and heart failure in pregnancy","name_fa":"درد قفسه سینه، MI و نارسایی قلبی در بارداری","cc":["chest-pain","dyspnea"],"keywords":"chest pain in pregnancy, myocardial infarction pregnancy, aortic dissection, cardiomyopathy, nitroprusside, درد قفسه سینه بارداری","status":"draft","features":["علل مشابه غیرحامله؛ دیسکسیون آئورت و کاردیومیوپاتی ممکن است مرتبط با بارداری باشند","MI در بارداری: آسپیرین، هپارین و PCI به‌جای ترومبولیتیک","CHF و ادم ریه: درمان استاندارد به‌جز sodium nitroprusside (تجمع تیوسیانات و سیانید در جنین)"],"ddx":[{"n":"Acute coronary syndrome |","cm":1},{"n":"Aortic dissection |","cm":1},{"n":"Pulmonary embolism |","cm":1},{"n":"Peripartum cardiomyopathy |"}],"redflags":["ایسکمی، افت فشار، هیپوکسی"],"guide":"MI: aspirin، heparin و PCI نه ترومبولیتیک. CHF/ادم ریه: درمان استاندارد بدون نیتروپروساید. به PE و دیسکسیون در بارداری فکر کن.","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 61: Emergencies After 20 Weeks of Pregnancy and The Postpartum Period, pp. 335–339"},"bleeding-late-pregnancy":{"id":"bleeding-late-pregnancy","variants":[{"id":"bleeding-late-unstable","o":{"I":[{"t":"Transabdominal ultrasound before speculum or digital pelvic examination (contraindicated in previa); transvaginal if nondiagnostic (by an experienced operator)"}],"L":[{"t":"Type and cross, baseline coagulation studies, electrolytes; DIC profile if placental abruption suspected"}],"S":[{"t":"Hemodynamic instability: IV normal saline or packed red blood cells"}],"T":[{"t":"Rh (D) immune globulin 300 μg IM for Rh-negative patients"},{"t":"Do not use tocolytics in suspected abruption"}],"Co":[{"t":"Emergent obstetric consultation (may need emergent cesarean delivery)"}]},"name":"Placental abruption / placenta previa with bleeding","level":"I","imp":"Vaginal bleeding in late pregnancy (abruption / previa)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۳۳ ساله با حاملگی ۳۶ هفته، خونریزی واژینال و درد شکم، فشار 85/50 پس از تصادف.","why":"ناپایداری و احتمال سزارین اورژانس؛ سونوگرافی قبل از معاینه واژینال."}],"ch":"61","name":"Vaginal bleeding in the second half of pregnancy (placental abruption, placenta previa)","name_fa":"خونریزی واژینال در نیمه دوم بارداری (جدا شدن جفت، جفت سرراهی)","cc":["vaginal-bleeding","pregnancy"],"keywords":"placental abruption, placenta previa, DIC, Rh immune globulin, tocolytics contraindicated, جدا شدن جفت, جفت سرراهی","status":"draft","features":["شایع‌ترین علل: جدا شدن جفت، جفت سرراهی و زایمان زودرس","abruption: جدا شدن زودرس جفت؛ در هر زن نزدیک ترم با خونریزی دردناک؛ خونریزی، درد شکم، تندرنس رحم، انقباضات هیپرتونیک، افزایش تون، دیسترس جنین، DIC و مرگ جنین/مادر؛ > 50٪ جفت معمولاً مرگ جنین؛ بعد از ترومای حتی خفیف","previa: لانه‌گزینی جفت روی os سرویکس؛ خونریزی بدون درد قرمز روشن و غالباً زیاد (برخلاف bloody show)","سونوگرافی ترانس‌ابدومینال قبل از معاینه اسپکولوم یا دیجیتال (در previa ممنوع)؛ ترانس‌واژینال در صورت نامشخص توسط فرد باتجربه؛ حساس برای previa، محدود برای abruption"],"ddx":[{"n":"Placental abruption |","cm":1},{"n":"Placenta previa |","cm":1},{"n":"Preterm labor / bloody show |"},{"n":"Uterine rupture |"}],"redflags":["شوک، DIC، دیسترس جنین، بعد از ترومای شکم"],"guide":"ناپایداری: NS وریدی یا PRBC. مشاوره اورژانس مامایی؛ CBC، type and cross، انعقاد و الکترولیت؛ DIC profile در شک به abruption؛ Rh(D) immune globulin 300 μg IM در Rh منفی؛ سزارین اورژانس ممکن؛ tocolytic ممنوع در abruption.","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 61: Emergencies After 20 Weeks of Pregnancy and The Postpartum Period, pp. 335–339"},"prom-preterm-labor":{"id":"prom-preterm-labor","variants":[{"id":"prom-stable","o":{"L":[{"t":"Sterile speculum examination: pool of fluid in the posterior fornix with pH > 7.0 and ferning pattern on smear; tests for chlamydia, gonorrhea, bacterial vaginosis and group B Streptococcus"}],"A":[{"t":"Antibiotics and steroids may be appropriate","fl":[{"k":"note","v":"drugs and doses not given in the book"}]}],"Co":[{"t":"Obstetrics consultation for treatment and admission decisions"}]},"name":"Premature rupture of membranes","level":"II","imp":"Premature rupture of membranes","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۲۸ ساله با حاملگی ۳۲ هفته، خروج ناگهانی مایع از واژن.","why":"تأیید با اسپکولوم استریل؛ پرهیز از معاینه دیجیتال؛ مشاوره مامایی."},{"id":"preterm-labor","o":{"I":[{"t":"Ultrasound for fetal age, weight, anatomy and amniotic fluid level if possible (obstetric consultation should not be delayed awaiting results)"}],"L":[{"t":"Cervical fluid examined for possible PROM; tests for chlamydia, gonorrhea, bacterial vaginosis and group B Streptococcus"}],"T":[{"t":"Monitor mother and fetus"},{"t":"If tocolytics are initiated and gestational age < 34 weeks: Dexamethasone 6 mg IM (glucocorticoid for fetal lung maturity)","fl":[{"k":"ci","v":"no tocolytics if placental abruption suspected"}]}],"Co":[{"t":"Obstetrician for admission and tocolytic decisions; transfer to a tertiary care center with a high-risk ICU if < 34 weeks"}]},"name":"Preterm labor (< 37 weeks)","level":"II","imp":"Preterm labor","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"زنی ۲۹ ساله با حاملگی ۳۱ هفته، انقباضات منظم و اتساع ۳ cm.","why":"پایش مادر و جنین؛ مشاوره مامایی برای tocolytic و استروئید."}],"ch":"61","name":"Premature rupture of membranes and preterm labor","name_fa":"پارگی زودرس کیسه آب و زایمان زودرس","cc":["pregnancy"],"keywords":"PROM, premature rupture of membranes, ferning, nitrazine, preterm labor, tocolytics, dexamethasone, group B Streptococcus, پارگی کیسه آب","status":"draft","features":["PROM: پارگی غشاها قبل از شروع زایمان؛ خروج ناگهانی یا نشت مداوم مایع؛ تأیید: برکه مایع در فورنیکس خلفی با pH > 7.0 و ferning","معاینه با اسپکولوم استریل؛ معاینه دیجیتال لگن پرهیز (افزایش عفونت و کاهش دوره نهفته)","تست کلامیدیا، گنوره، BV و GBS","زایمان زودرس: < 37 هفته؛ انقباضات منظم با افاسمان و اتساع سرویکس","معاینه دیجیتال (دستکش استریل) فقط بعد از رد PROM و previa","سونوگرافی برای سن، وزن، آناتومی و مایع آمنیوتیک در صورت امکان؛ مشاوره نباید به تأخیر بیفتد"],"ddx":[{"n":"Placental abruption / placenta previa |","cm":1},{"n":"Chorioamnionitis |","cm":1},{"n":"Urinary leakage / vaginal discharge |"}],"redflags":["تب، دیسترس جنین، خونریزی"],"guide":"PROM: درمان وابسته به سن حاملگی و بلوغ جنین، وضعیت جنین، نگرانی عفونت؛ ممکن است آنتی‌بیوتیک و استروئید؛ مشاوره مامایی برای درمان و بستری. زایمان زودرس: پایش مادر و جنین؛ مشاوره مامایی برای بستری و تصمیم tocolytic؛ اگر tocolytic آغاز شد و سن < 34 هفته: گلوکوکورتیکوئید برای بلوغ ریه جنین (dexamethasone 6 mg IM شایع)؛ tocolytic ممنوع در شک به abruption؛ < 34 هفته: انتقال به مرکز با NICU در صورت امکان.","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 61: Emergencies After 20 Weeks of Pregnancy and The Postpartum Period, pp. 335–339"},"postpartum-hemorrhage":{"id":"postpartum-hemorrhage","variants":[{"id":"pph-atony","o":{"L":[{"t":"Clotting studies; type and cross"}],"S":[{"t":"Stabilization with crystalloid IV fluids and/or packed red blood cells if needed"}],"T":[{"t":"Uterine massage and Oxytocin 20 units in one liter of normal saline IV at 200 mL/h (uterine atony)"},{"t":"Minor lacerations may be repaired in the ED; vagina and cervix inspected for lacerations"}],"Co":[{"t":"Emergency operative treatment by the obstetrician (extensive lacerations, retained products of conception, uterine inversion or uterine rupture)"}]},"name":"Postpartum hemorrhage","level":"I","imp":"Postpartum hemorrhage","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۳۰ ساله ۶ ساعت پس از زایمان با خونریزی شدید، رحم بزرگ و خمیری و فشار 80/50.","why":"آتونی شایع‌ترین علت؛ احیا، ماساژ رحم و oxytocin."}],"ch":"61","name":"Postpartum hemorrhage","name_fa":"خونریزی پس از زایمان","cc":["vaginal-bleeding","hypotension-shock"],"keywords":"postpartum hemorrhage, uterine atony, oxytocin, retained products, uterine inversion, uterine rupture, خونریزی بعد از زایمان","status":"draft","features":["روز اول: آتونی رحم، پارگی رحم، پارگی دستگاه تناسلی تحتانی، بافت جفت باقیمانده، اینورژن رحم، کواگولوپاتی؛ بعد از 24 ساعت: باقیمانده محصولات، پولیپ رحم، کواگولوپاتی (vWD)","رحم بزرگ و خمیری: آتونی؛ توده واژینال: اینورژن؛ خونریزی با تون و اندازه خوب: باقیمانده یا پارگی رحم","واژن و سرویکس را برای پارگی بازرسی کن"],"ddx":[{"n":"Uterine atony |","cm":1},{"n":"Uterine rupture / inversion |","cm":1},{"n":"Retained products of conception |"},{"n":"Genital tract laceration |"},{"n":"Coagulopathy |"}],"redflags":["شوک، توده واژینال، ادامه خونریزی با تون خوب"],"guide":"اولویت اول: تثبیت با کریستالوئید و/یا PRBC؛ CBC، انعقاد، type and cross. آتونی: ماساژ رحم و oxytocin 20 واحد در یک لیتر نرمال سالین IV با 200 mL/h. پارگی‌های جزئی در ED ترمیم می‌شود؛ پارگی وسیع، باقیمانده، اینورژن یا پارگی رحم: عمل اورژانس توسط متخصص زنان.","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 61: Emergencies After 20 Weeks of Pregnancy and The Postpartum Period, pp. 335–339"},"postpartum-endometritis-mastitis":{"id":"postpartum-endometritis-mastitis","variants":[{"id":"endometritis-postpartum","o":{"L":[{"t":"Urinalysis and cervical cultures"}],"A":[{"t":"Inpatient: Clindamycin 450 to 900 mg IV every 8 hours plus Gentamicin 1.5 mg/kg IV every 8 hours, or Cefoxitin 1 to 2 g IV every 6 hours","fl":[{"k":"renal","v":"aminoglycoside"}]},{"t":"Outpatient regimens may include Clindamycin or Doxycycline","fl":[{"k":"ci","v":"do not use doxycycline in breastfeeding patients"},{"k":"note","v":"outpatient doses not given in the book"}]}],"Co":[{"t":"Admission for ill-appearing patients, after cesarean section, or with comorbidities; obstetrician"}]},"name":"Postpartum endometritis","level":"II","imp":"Postpartum endometritis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زنی ۲۷ ساله ۴ روز پس از سزارین با تب، درد زیر شکم و ترشح بدبو.","why":"سزارین یا بدحال: بستری و آنتی‌بیوتیک وریدی."},{"id":"mastitis-postpartum","o":{"I":[{"t":"Bedside ultrasound to differentiate mastitis from breast abscess"}],"A":[{"t":"Dicloxacillin 500 mg orally four times daily, or Cephalexin 500 mg orally four times daily"},{"t":"Penicillin allergy or MRSA concern: Clindamycin 300 mg PO every 6 hours"}],"T":[{"t":"Oral analgesics as needed","fl":[{"k":"note","v":"drug and dose not given in the book"}]},{"t":"Continue nursing on the affected breast (in cases of purulent discharge, pump and discard the milk rather than nurse)"}]},"name":"Mastitis","level":"III","imp":"Mastitis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۲۸ ساله شیرده با قرمزی، تورم و درد پستان راست و تب.","why":"ماستیت با آنتی‌بیوتیک خوراکی و ادامه شیردهی؛ سونوگرافی برای رد آبسه."}],"ch":"61","name":"Postpartum endometritis and mastitis","name_fa":"آندومتریت پس از زایمان و ماستیت","cc":["fever","abdominal-pain"],"keywords":"postpartum endometritis, mastitis, breast abscess, clindamycin, gentamicin, cefoxitin, dicloxacillin, cephalexin, ماستیت","status":"draft","features":["آندومتریت: عفونت پلی‌میکروبیال، چند روز پس از زایمان؛ تب، درد تحتانی شکم، لوشیای بدبو؛ تندرنس رحم/سرویکس و ترشح","ماستیت: سلولیت بافت اطراف غدد پستان؛ تورم، قرمزی، تندرنس و احتقان بخشی از پستان با یا بدون تب و لرز؛ stasis شیر مشابه ولی بدون اریتم، تب یا لرز","تمایز ماستیت از آبسه پستان با سونوگرافی بالین"],"ddx":[{"n":"Breast abscess |","cm":1},{"n":"Sepsis from endometritis |","cm":1},{"n":"Milk stasis |"},{"n":"Wound infection / UTI |"}],"redflags":["ظاهر بیمار، سزارین، بیماری زمینه‌ای، ترشح چرکی"],"guide":"آندومتریت: CBC، UA و کشت سرویکس؛ بستری برای آنتی‌بیوتیک در بدحال، سزارین یا بیماری زمینه‌ای؛ سرپایی: clindamycin یا doxycycline (در شیردهی doxycycline ممنوع)؛ بستری: clindamycin 450 تا 900 mg IV هر 8 ساعت + gentamicin 1.5 mg/kg IV هر 8 ساعت یا cefoxitin 1 تا 2 g IV هر 6 ساعت. ماستیت: dicloxacillin 500 mg PO چهار بار روزانه یا cephalexin 500 mg چهار بار روزانه؛ clindamycin 300 mg PO هر 6 ساعت در آلرژی پنی‌سیلین یا نگرانی MRSA؛ ضددرد خوراکی؛ ادامه شیردهی از پستان درگیر (در ترشح چرکی: دوشیدن و دور ریختن شیر).","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 61: Emergencies After 20 Weeks of Pregnancy and The Postpartum Period, pp. 335–339"},"amniotic-fluid-embolism":{"id":"amniotic-fluid-embolism","variants":[{"id":"afe-suspected","o":{"T":[{"t":"Supportive treatment: treat hypoxia, hypotension and hypoperfusion","fl":[{"k":"note","v":"specific orders not given in the book"}]}],"Co":[{"t":"Obstetrician; ICU"}]},"name":"Suspected amniotic fluid embolism","level":"I","imp":"Amniotic fluid embolism","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"زنی در حین زایمان با افت فشار ناگهانی، هیپوکسی، تشنج و دیسترس جنین.","why":"درمان کاملاً حمایتی."}],"ch":"61","name":"Amniotic fluid embolism","name_fa":"آمبولی مایع آمنیوتیک","cc":["hypotension-shock","dyspnea"],"keywords":"amniotic fluid embolism, cardiovascular collapse, DIC, آمبولی مایع آمنیوتیک","status":"draft","features":["بیماری ناگهانی فاجعه‌بار با مرگ‌ومیر 60٪ تا 80٪","کولاپس قلبی-عروقی ناگهانی با هیپوکسمی، ادم ریه، تغییر هوشیاری، تشنج و DIC همراه دیسترس ناگهانی جنین؛ مرگ می‌تواند سریع رخ دهد"],"ddx":[{"n":"Pulmonary embolism |","cm":1},{"n":"Eclampsia / peripartum cardiomyopathy |","cm":1},{"n":"Placental abruption |"},{"n":"Anaphylaxis / sepsis |"}],"redflags":["کولاپس قلبی-عروقی، هیپوکسمی، DIC"],"guide":"درمان حمایتی: هیپوکسی، هیپوتانسیون و هیپوپرفیوژن را درمان کن.","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 61: Emergencies After 20 Weeks of Pregnancy and The Postpartum Period, pp. 335–339"},"emergency-delivery":{"id":"emergency-delivery","variants":[{"id":"delivery-normal","o":{"I":[{"t":"Ultrasound to confirm fetal position if possible; ultrasound first if active vaginal bleeding (rule out placenta previa)"}],"L":[{"t":"Fetal heart monitoring; sterile speculum / bimanual examination (cervical dilation, rupture of membranes; Nitrazine paper and fern test)"}],"T":[{"t":"Left lateral decubitus position after examination; dorsal lithotomy position for delivery"},{"t":"Support the perineum with sterile towel and mild counter-pressure on the fetal head; mother breathes through contractions instead of pushing"},{"t":"Check for nuchal cord (loose: reduce over head; tight: two clamps and cut); gentle downward then upward traction for shoulders"},{"t":"Dry and stimulate infant; double clamp and cut the cord; warm incubator; Apgar at 1 and 5 minutes"},{"t":"Episiotomy if necessary: Lidocaine 1% 5 to 10 mL into the posterior fourchette and perineum, 2- to 3-cm cut at the midline or 45 degrees"},{"t":"Placenta allowed to separate spontaneously; gentle uterine massage; Oxytocin 10 to 40 U/1000 mL NS at a moderate rate, or 10 U IM"}],"Co":[{"t":"Notify obstetrician if available; laceration repair may be delayed until an experienced obstetrician can inspect for fourth-degree tears"}]},"name":"Imminent precipitous delivery (vertex)","level":"I","imp":"Imminent precipitous delivery","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"زنی ۲۸ ساله با حاملگی ۳۸ هفته، انقباضات هر ۲ دقیقه، اتساع کامل و سر در introitus.","why":"انتقال خطرناک است؛ آماده‌سازی زایمان؛ بیمار در لیتوتومی؛ اطلاع به متخصص زنان."},{"id":"delivery-cord-prolapse","o":{"T":[{"t":"Do not remove the examining hand; elevate the presenting fetal part to reduce compression of the cord"},{"t":"Keep the examining hand in the vagina during transport and preparation for surgery; do not attempt to reduce the cord"}],"Co":[{"t":"Immediate obstetric assistance (cesarean section indicated)"}]},"name":"Cord prolapse","level":"I","imp":"Umbilical cord prolapse","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"زنی ۳۰ ساله پس از پارگی کیسه آب با بند ناف نبض‌دار در واژن.","why":"فشار روی بند را با بالا نگه داشتن قسمت پرزانتاسیون برطرف کن؛ سزارین اورژانس."},{"id":"delivery-shoulder-dystocia","o":{"T":[{"t":"Suction the infant's nose and mouth; call for assistance"},{"t":"McRoberts maneuver: extreme lithotomy with legs sharply flexed up to the abdomen"},{"t":"Assistant applies downward suprapubic pressure to disimpact the anterior shoulder","fl":[{"k":"ci","v":"no fundal pressure"}]},{"t":"Woods corkscrew maneuver: fingertips behind the anterior shoulder and in back of the posterior shoulder, rotate the shoulder girdle 180°"}],"Co":[{"t":"Obstetrician"}]},"name":"Shoulder dystocia","level":"I","imp":"Shoulder dystocia","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"حین زایمان سر خارج شده و به پرینه چسبیده (turtle sign) و شانه قدامی نمی‌آید.","why":"مانورهای مرحله‌ای McRoberts، فشار سوپراپوبیک و Woods."},{"id":"delivery-breech","o":{"T":[{"t":"Frank and complete breech: allow the delivery to progress spontaneously (the presenting part dilates the cervix maximally); consult obstetrical texts for maneuvers"},{"t":"Footling and incomplete breech are not considered safe for vaginal delivery (cord prolapse, incomplete dilatation)"}],"Co":[{"t":"Immediate obstetric consultation"}]},"name":"Breech presentation","level":"I","imp":"Breech presentation","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"زنی ۲۹ ساله در لیبر با پرزانتاسیون بریچ.","why":"خطر اصلی گیر کردن سر؛ مشاوره فوری مامایی."}],"ch":"62","name":"Emergency delivery (normal, cord prolapse, shoulder dystocia, breech)","name_fa":"زایمان اورژانس (طبیعی، پرولاپس بند ناف، دیستوشی شانه، بریچ)","cc":["pregnancy"],"keywords":"emergency delivery, precipitous delivery, cord prolapse, shoulder dystocia, McRoberts maneuver, Woods corkscrew, breech, oxytocin, Apgar, زایمان اورژانس","status":"draft","features":["هر زن باردار > 20 هفته با لیبر فعال: ارزیابی سریع؛ علائم حیاتی مادر و مانیتور قلب جنین؛ FHR < 110 یا > 160 مداوم: دیسترس جنین","شرح حال: تکرر/زمان شروع انقباضات، نشت مایع، خونریزی، سن حاملگی، مراقبت پیش از زایمان؛ معاینه شکم (ارتفاع فوندوس، تندرنس، وضعیت جنین)؛ دوهمی یا اسپکولوم استریل مگر مانع (خونریزی فعال)؛ بعد از معاینه: دکوبیتوس جانبی چپ","لیبر کاذب (Braxton–Hicks): انقباضات نامنظم، کوتاه، معمولاً بدون درد و تحتانی شکم؛ لیبر حقیقی: انقباضات دردناک منظم با افزایش تدریجی و اتساع سرویکس؛ از فوندوس به لگن و کمر","پارگی کیسه آب: گاش مایع شفاف یا خونی؛ مایع آمنیوتیک قلیایی، Nitrazine آبی تیره و ferning؛ مکونیوم را ثبت کن؛ در پره‌ترم که طولانی کردن بارداری لازم است معاینه دیجیتال را پرهیز","خونریزی فعال: ابتدا سونوگرافی برای رد جفت سرراهی","اگر سرویکس باز و انقباض فعال: انتقال حتی کوتاه خطرناک؛ آماده‌سازی زایمان اورژانس"],"ddx":[{"n":"Cord prolapse |","cm":1},{"n":"Shoulder dystocia |","cm":1},{"n":"Placenta previa / abruption |","cm":1},{"n":"Breech presentation |"},{"n":"False labor (Braxton-Hicks) |"}],"redflags":["بند ناف نبض‌دار در معاینه، turtle sign، FHR غیرطبیعی، خونریزی فعال، بریچ فوتلینگ"],"guide":"# زایمان طبیعی\nوضعیت لیتوتومی پشتی؛ ارزیابی وضعیت جنین (سونوگرافی در صورت امکان)؛ اطلاع به متخصص زنان. 1) کنترل خروج سر: حمایت پرینه با حوله استریل، فشار مخالف ملایم (جلوگیری از پارگی درجه 3 و 4)، کنترل چانه با دست تحتانی؛ از مادر بخواه حین انقباض نفس بکشد و زور نزند. 2) بعد از سر، گردن را برای بند دور گردن لمس کن (تا 35٪): شل: از روی سر رد کن؛ محکم: دو کلمپ و برش. 3) چرخش سر؛ کشش ملایم رو به پایین برای شانه قدامی، سپس بالا برای شانه خلفی. 4) دست خلفی زیر زیربغل و دست قدامی مچ پاها. 5) پیچیدن نوزاد در حوله و تحریک و خشک کردن. 6) دو کلمپ بند ناف و برش با قیچی استریل. 7) انکوباتور گرم و Apgar در 1 و 5 دقیقه (رنگ، تون، ضربان قلب، تلاش تنفسی، رفلکس). 8) اپیزیوتومی (مثلاً بریچ): lidocaine 1٪ 5 تا 10 mL در فورشت خلفی و پرینه؛ برش 2 تا 3 cm در خط وسط یا 45 درجه؛ حمایت دستی تا امتداد به رکتوم نیابد.\n# پس از زایمان\nجفت خودبه‌خود جدا شود با کشش ملایم؛ کشش شدید: اینورژن رحم، پارگی بند یا جفت و خونریزی شدید؛ ماساژ رحم؛ oxytocin 10 تا 40 U/1000 mL NS با سرعت متوسط یا 10 U IM؛ ترمیم پارگی/اپیزیوتومی را می‌توان تا حضور متخصص با تجربه (بررسی پارگی درجه 4) به تعویق انداخت.\n# پرولاپس بند\nبند نبض‌دار: دست معاینه‌گر را خارج نکن و قسمت پرزانتاسیون را بالا ببر؛ کمک فوری مامایی (سزارین)؛ دست را در واژن نگه دار حین انتقال؛ بند را جا نینداز.\n# دیستوشی شانه\nturtle sign؛ ساکشن بینی و دهان، کمک گرفتن و وضعیت McRoberts؛ فشار سوپراپوبیک رو به پایین؛ فشار فوندوس ممنوع؛ Woods corkscrew: چرخش ۱۸۰ درجه کمربند شانه.\n# بریچ\nخطر گیر کردن سر؛ مشاوره فوری مامایی؛ frank و complete: اجازه پیشرفت خودبه‌خودی؛ footling و incomplete: زایمان واژینال ایمن نیست (پرولاپس بند و اتساع ناکامل).","pearls":["هرگز فشار فوندوس در دیستوشی شانه.","بند ناف را بازگردانی نکن؛ دست را داخل واژن نگه دار."],"section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 62: Emergency Delivery, pp. 340–343"},"vulvovaginitis":{"id":"vulvovaginitis","variants":[{"id":"vaginitis-bv","o":{"L":[{"t":"Vaginal pH, amine test (10% KOH), saline wet preparation (clue cells)"}],"A":[{"t":"Metronidazole 500 mg PO twice daily for 7 days; alternatives: Clindamycin 2% intravaginal cream at night for 7 days or Metronidazole 0.75% intravaginal gel daily for 5 days"},{"t":"Metronidazole 250 mg PO twice daily for 7 days","if":"pregnant, symptomatic","fl":[{"k":"ci","v":"avoid alcohol during treatment and for 24 hours after (disulfiram-like reaction); no treatment for male partners or asymptomatic women"}]}]},"name":"Bacterial vaginosis","level":"III","imp":"Bacterial vaginosis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۲۵ ساله با ترشح بدبو (بوی ماهی)؛ pH 5 و clue cells.","why":"BV با metronidazole؛ پرهیز از الکل."},{"id":"vaginitis-candida","o":{"L":[{"t":"Vaginal pH and microscopy with 10% KOH (budding yeast or pseudohyphae)"}],"A":[{"t":"Fluconazole 150 mg PO single dose; or topical azoles (clotrimazole, butoconazole, miconazole, terconazole, tioconazole)"},{"t":"intravaginal agents for 7 days","if":"pregnant","fl":[{"k":"ci","v":"avoid oral fluconazole in pregnancy"}]},{"t":"Fluconazole 150 mg PO on days 1 and 3","if":"complicated, nonpregnant"}]},"name":"Candida vaginitis","level":"III","imp":"Candida vaginitis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۳۰ ساله با خارش و ترشح پنیری پس از آنتی‌بیوتیک.","why":"fluconazole دوز واحد؛ در بارداری داخل واژینال."},{"id":"vaginitis-trichomonas","o":{"L":[{"t":"Saline wet prep immediately after sampling (motile, pear-shaped flagellated trichomonads); point-of-care PCR where available"}],"A":[{"t":"Metronidazole 2 g single oral dose, or Tinidazole 2 g single oral dose; if single-dose therapy fails: Metronidazole 500 mg twice daily for 7 days","fl":[{"k":"ci","v":"metronidazole gel is not recommended"}]}],"T":[{"t":"Treat sexual partners; abstain from sexual activity until the treatment course is completed and asymptomatic"}]},"name":"Trichomonas vaginitis","level":"III","imp":"Trichomonas vaginitis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۲۲ ساله با ترشح کف‌آلود بدبو و خارش.","why":"درمان دوز واحد و درمان شریک."},{"id":"vaginitis-other","o":{"T":[{"t":"Contact: remove the precipitant; cool sitz baths, compresses with Burow's solution, topical corticosteroids; oral antihistamines if true allergy"},{"t":"Atrophic: topical estrogen creams","fl":[{"k":"ci","v":"not in the emergency department for women with prior reproductive tract cancer or postmenopausal bleeding"}]},{"t":"Vaginal foreign body: removal of the object"},{"t":"Bartholin abscess: incision and drainage with placement of a Word catheter; Bartholin cyst without abscess: broad-spectrum antibiotics, analgesics and sitz baths","fl":[{"k":"note","v":"drugs and doses not given in the book"}]}],"Co":[{"t":"Referral for definitive surgical management (Bartholin abscess)"}]},"name":"Contact / atrophic vaginitis, vaginal foreign body, Bartholin abscess","level":"III","imp":"Vulvovaginitis (contact / atrophic / foreign body / Bartholin)","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۶۰ ساله با خارش و سوزش و ترشح چرکی کم؛ یا زنی ۳۰ ساله با تورم دردناک لابیا.","why":"درمان بر اساس علت: استروژن موضعی، برداشتن جسم، یا درناژ بارتولن."}],"ch":"63","name":"Vulvovaginitis (bacterial vaginosis, candidiasis, trichomoniasis, contact, atrophic, foreign body, Bartholin abscess)","name_fa":"ولوواژینیت (BV، کاندیدا، تریکومونا، تماسی، آتروفیک، جسم خارجی، آبسه بارتولن)","cc":["genital-complaint","vaginal-bleeding"],"keywords":"bacterial vaginosis, candida vaginitis, trichomonas, metronidazole, fluconazole, tinidazole, atrophic vaginitis, Bartholin abscess, Word catheter, واژینیت","status":"draft","features":["علل: عفونت، محرک، آلرژی، جسم خارجی و آتروفی؛ فلور طبیعی pH 3.8 تا 4.5","BV: شایع‌ترین علت ترشح بدبو؛ تا 50٪ بدون علامت؛ جایگزینی لاکتوباسیل با بی‌هوازی (Gardnerella و ...)؛ ترشح «بوی ماهی»؛ تشخیص با 3 از 4: ترشح، pH > 4.5، تست آمین مثبت (KOH 10٪)، clue cells","کاندیدا: دومین علت شایع؛ عوامل: آنتی‌بیوتیک سیستمیک، دیابت، بارداری، HRT، OCP؛ خارش، ترشح، دیزوری خارجی، دیسپارونی؛ ادم/اریتم و ترشح «پنیری»؛ pH 4 تا 4.5 و مخمر جوانه‌دار/پسودوهیف در میکروسکوپی (KOH 10٪: حساسیت 80٪)","تریکومونا: STD؛ ترشح کف‌آلود و بدبو، خارش و تحریک؛ تا 50٪ بدون علامت؛ wet prep: تریکومونادهای متحرک گلابی‌شکل (حساسیت 60٪ تا 70٪؛ بلافاصله ببین)؛ کشت 95٪؛ PCR نقطه مراقبت","تماسی: دوش، صابون، حباب‌حمام، دئودورانت، عطر، بهداشتی، آنتی‌بیوتیک موضعی، لباس تنگ؛ سوزش، خارش و تورم؛ قرمزی، ادم، زخم؛ ممکن است کاندیدا همراه شود","جسم خارجی: ترشح بدبو یا خونی مزمن؛ کودکان: کاغذ توالت، اسباب‌بازی؛ بزرگسالان: تامپون فراموش‌شده، بسته مواد، وسایل جنسی؛ برداشتن درمان قطعی","آتروفیک: بعد از یائسگی؛ خونریزی، pH بالا، ترشح چرکی؛ کرم استروژن موضعی","بارتولن: غده در لابیای کوچک ساعت 4 و 8؛ کیست/آبسه؛ درد و تورم طی چند روز؛ ایندوراسیون و فلوکتواسیون"],"ddx":[{"n":"Pelvic inflammatory disease |","cm":1},{"n":"Sexually transmitted infection (gonorrhea, chlamydia) |","cm":1},{"n":"Bacterial vaginosis / candida / trichomonas |"},{"n":"Vaginal foreign body |"},{"n":"Atrophic vaginitis / contact dermatitis |"}],"redflags":["ترشح چرکی با درد لگن/CMT (PID)، خونریزی پس از یائسگی (سرطان)"],"guide":"BV: metronidazole 500 mg PO دو بار روزانه 7 روز؛ جایگزین: clindamycin 2٪ کرم داخل واژینال شبانه 7 روز یا metronidazole 0.75٪ ژل روزانه 5 روز؛ شریک مذکر و بدون علامت درمان نمی‌شود؛ الکل ممنوع حین درمان و 24 ساعت بعد؛ حاملگی علامت‌دار درمان شود: metronidazole 250 mg PO دو بار روزانه 7 روز.\nکاندیدا: fluconazole 150 mg PO دوز واحد یا آزول موضعی (clotrimazole، butoconazole، miconazole، terconazole، tioconazole)؛ حاملگی: داخل واژینال 7 روز و پرهیز از fluconazole خوراکی؛ پیچیده: fluconazole 150 mg روز 1 و 3.\nتریکومونا: metronidazole 2 g یا tinidazole 2 g خوراکی دوز واحد؛ شکست: metronidazole 500 mg دو بار روزانه 7 روز؛ ژل ضعیف؛ درمان شریک و پرهیز تا اتمام درمان.\nتماسی: حذف محرک؛ سیتز سرد، کمپرس Burow، کورتیکواستروئید موضعی؛ آنتی‌هیستامین خوراکی در آلرژی؛ درمان کاندیدا همراه.\nآتروفیک: کرم استروژن موضعی (در ED برای زنان با سرطان دستگاه تناسلی یا خونریزی پس از یائسگی تجویز نشود).\nبارتولن: بدون آبسه: آنتی‌بیوتیک وسیع‌الطیف، ضددرد و سیتز؛ آبسه: برش و درناژ با گذاشتن Word catheter و ارجاع جراحی.","pearls":["الکل در متروندازول ممنوع (واکنش شبه‌دی‌سولفیرام)."],"section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 63: Vulvovaginitis, pp. 344–346"},"pelvic-inflammatory-disease":{"id":"pelvic-inflammatory-disease","variants":[{"id":"pid-outpatient","o":{"I":[{"t":"Transvaginal ultrasound (or MRI) if tubo-ovarian complex suspected","fl":[{"k":"note","v":"specific criteria; not mandatory"}]}],"L":[{"t":"Pregnancy test; wet preparation of vaginal secretions; DNA probe or culture for N. gonorrhoeae and Chlamydia trachomatis; HIV testing or referral (do not delay treatment pending results)"}],"A":[{"t":"Ceftriaxone 250 mg IM once, or Cefoxitin 2 g IM once and Probenecid 1 g PO once concurrently; or other parenteral third-generation cephalosporin (ceftizoxime or cefotaxime)"},{"t":"plus Doxycycline 100 mg PO twice a day for 14 days with or without Metronidazole 500 mg PO twice a day for 14 days"},{"t":"If parenteral cephalosporin not feasible and fluoroquinolone resistance is low: Levofloxacin 500 mg PO or Ofloxacin 400 mg twice daily for 14 days with or without Metronidazole 500 mg PO twice a day for 14 days","fl":[{"k":"ci","v":"fluoroquinolones are no longer recommended to treat gonorrhea"}]}],"T":[{"t":"Adequate analgesia","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Reevaluate in the ED or by gynecologist within 72 hours; patient and sexual partner(s) complete the full treatment course before resuming sexual activity"}]},"name":"PID, mild to moderate (outpatient)","level":"III","imp":"Pelvic inflammatory disease","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۲۲ ساله با درد زیر شکم، ترشح واژینال، CMT و تب خفیف؛ تحمل خوراکی دارد.","why":"PID خفیف تا متوسط با درمان خوراکی و ضددرد؛ بازارزیابی 72 ساعته."},{"id":"pid-inpatient","o":{"I":[{"t":"Transvaginal ultrasound (or MRI): thickened fluid-filled tubes with or without free pelvic fluid or tubo-ovarian complex"}],"L":[{"t":"Pregnancy test; wet preparation; DNA probe or culture for N. gonorrhoeae and Chlamydia trachomatis; ESR or C-reactive protein"}],"A":[{"t":"Cefotetan 2 g IV every 12 h, or Cefoxitin 2 g IV every 6 h, plus Doxycycline 100 mg PO or IV every 12 h"},{"t":"Or Clindamycin 900 mg IV every 8 h plus Gentamicin 2 mg/kg IV or IM loading dose followed by 1.5 mg/kg every 8 h (or 3 to 5 mg/kg every 24 h)","fl":[{"k":"renal","v":"aminoglycoside"}]},{"t":"Alternative (limited data): Ampicillin/sulbactam 3 g IV every 6 h plus Doxycycline 100 mg PO or IV every 12 h"}],"Co":[{"t":"Admission; gynecology"}]},"name":"PID, severe or complicated (admission)","level":"II","imp":"Pelvic inflammatory disease (severe / tubo-ovarian abscess)","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۲۵ ساله با تب 39، استفراغ، درد شدید زیر شکم و توده آدنکس در سونوگرافی.","why":"استفراغ، ظاهر سمی یا آبسه توبواوارین: بستری و آنتی‌بیوتیک وریدی."}],"ch":"64","name":"Pelvic inflammatory disease","name_fa":"بیماری التهابی لگن (PID)","cc":["abdominal-pain","vaginal-bleeding","genital-complaint","fever"],"keywords":"PID, salpingitis, tubo-ovarian abscess, cervical motion tenderness, cefoxitin, cefotetan, ceftriaxone, doxycycline, metronidazole, PID لگن","status":"draft","features":["طیف عفونت‌های دستگاه تناسلی فوقانی: آندومتریت، سالپنژیت، آبسه توبواوارین، پریتونیت لگنی؛ N. gonorrhoeae و C. trachomatis و فلور واژن، گرم‌منفی، استرپتوکوک، مایکوپلاسما","عوامل خطر: نوجوانی، شرکای متعدد، شریک جدید در 30 روز، STD دیگر، قرار دادن IUD در 3 هفته قبل؛ در بارداری کمتر ولی با عوارض مادری و زایمان زودرس","عوارض: افزایش خطر EP، ناباروری و درد مزمن حتی پس از یک اپیزود","درد تحتانی شکم (> 90٪)، ترشح واژینال (75٪)، خونریزی، ناراحتی ادراری، تب، تهوع/استفراغ؛ علائم می‌تواند خفیف باشد","معاینه: تندرنس تحتانی شکم، CMT یا تندرنس رحم/آدنکس؛ سرویسیت موکوپورولنت شایع؛ نبودش علل دیگر را مطرح می‌کند","جدول 64-1: حداقل معیار: تندرنس رحم/آدنکس یا CMT (درمان تجربی اگر علت دیگری نیست)؛ معیار تکمیلی: دمای دهانی > 38.3°C، ترشح موکوپورولنت، ESR/CRP بالا، شواهد آزمایشگاهی گنوکوک/کلامیدیا؛ اختصاصی: لاپاروسکوپی، سونوگرافی ترانس‌واژینال/MRI (لوله‌های ضخیم پر از مایع یا کمپلکس توبواوارین)، بیوپسی اندومتر","هیچ تست آزمایشگاهی منفرد حساس یا اختصاصی نیست"],"ddx":[{"n":"Ectopic pregnancy |","cm":1},{"n":"Tubo-ovarian abscess |","cm":1},{"n":"Gastroenteritis / diverticulitis / appendicitis |"},{"n":"Spontaneous or septic abortion |"},{"n":"Ovarian cyst / pyelonephritis / renal colic |"}],"redflags":["ظاهر سمی، عدم تحمل خوراکی، حاملگی، نقص ایمنی، آبسه توبواوارین، نمی‌توان اورژانس جراحی را رد کرد"],"guide":"درمان نباید تا نتایج تست به تعویق بیفتد. آزمایش: تست حاملگی، wet prep ترشحات واژن، DNA probe یا کشت گنوکوک و کلامیدیا.\n# سرپایی (جدول 64-3)\nceftriaxone 250 mg IM یک‌بار یا cefoxitin 2 g IM یک‌بار + probenecid 1 g PO همزمان (یا سفالوسپورین نسل سوم دیگر ceftizoxime/cefotaxime) به‌علاوه doxycycline 100 mg PO دو بار روزانه 14 روز با یا بدون metronidazole 500 mg PO دو بار روزانه 14 روز. اگر سفالوسپورین تزریقی ممکن نیست و مقاومت کم: levofloxacin 500 mg PO یا ofloxacin 400 mg دو بار روزانه 14 روز با یا بدون metronidazole؛ فلوروکینولون برای گنوره توصیه نمی‌شود.\n# تزریقی (جدول 64-2)\ncefotetan 2 g IV هر 12 ساعت یا cefoxitin 2 g IV هر 6 ساعت + doxycycline 100 mg PO/IV هر 12 ساعت؛ یا clindamycin 900 mg IV هر 8 ساعت + gentamicin 2 mg/kg IV/IM بار سپس 1.5 mg/kg هر 8 ساعت (یا 3 تا 5 mg/kg هر 24 ساعت)؛ جایگزین: ampicillin/sulbactam 3 g IV هر 6 ساعت + doxycycline.\n# بستری\nظاهر سمی، عدم تحمل خوراکی، تهوع/استفراغ، عدم رد تشخیص جایگزین یا اورژانس جراحی، شکست درمان سرپایی، حاملگی، نقص ایمنی، نگرانی عدم همکاری، آبسه توبواوارین. سرپایی: بازارزیابی ظرف 72 ساعت. مشاوره پیشگیری و تست HIV؛ شریک‌ها درمان شوند و تا پایان درمان رابطه نداشته باشند.","pearls":["نبود سرویسیت موکوپورولنت: علل دیگر درد لگن را بیشتر مدنظر بگیر."],"section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 64: Pelvic Inflammatory Disease, pp. 347–349"},"gyn-procedure-complications":{"id":"gyn-procedure-complications","variants":[{"id":"gynproc-infection-cuff","o":{"L":[{"t":"Sterile speculum and bimanual examination"}],"A":[{"t":"Broad-spectrum antibiotics: Imipenem-cilastatin, or Gentamicin and Clindamycin, or Ciprofloxacin plus Metronidazole","fl":[{"k":"note","v":"doses not given in the book"}]},{"t":"antibiotic treatment directed at methicillin-resistant Staphylococcus aureus and streptococci","if":"wound infection","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"T":[{"t":"drainage","if":"wound infection"}],"Co":[{"t":"Admit for continued antibiotics and consideration of drainage by interventional radiology (cuff); consult the gynecologist who performed the procedure; admit invasive wound infections"}]},"name":"Postoperative infection (vaginal cuff cellulitis, wound infection)","level":"II","imp":"Postoperative gynecologic infection","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زنی ۴۵ ساله ۷ روز پس از هیستروکتومی با تب، درد لگن و ترشح چرکی؛ تندرنس cuff.","why":"cuff cellulitis با آنتی‌بیوتیک وسیع‌الطیف وریدی و بستری."},{"id":"gynproc-bowel-ureter","o":{"I":[{"t":"X-rays (ileus or free air under the diaphragm); CT scan with IV contrast or intravenous pyelogram for ureteral obstruction; CT / MRI for septic pelvic thrombophlebitis (do not exclude the disease if negative)"}],"L":[{"t":"Urinalysis; CBC"}],"A":[{"t":"IV antibiotics for septic pelvic thrombophlebitis","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"T":[{"t":"Anticoagulation for septic pelvic thrombophlebitis","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Early gynecology consultation; admission for ureteral catheterization and possible repair (delayed repair after percutaneous nephrostomy is also acceptable)"}]},"name":"Suspected bowel, ureteral or bladder injury / septic pelvic thrombophlebitis","level":"I","imp":"Postoperative visceral injury after gynecologic surgery","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"زنی ۳۸ ساله ۳ روز پس از لاپاروسکوپی با درد شدید دوطرفه زیر شکم، تب و پریتونیت.","why":"درد بیش از انتظار پس از لاپاروسکوپی: آسیب روده را فکر کن؛ مشاوره زودهنگام ژنیکولوژی."},{"id":"gynproc-bleeding-fistula","o":{"I":[{"t":"Pelvic ultrasound to confirm retained products of conception (induced abortion)"}],"T":[{"t":"Postconization bleeding: Monsel's solution, direct pressure for 5 minutes with a large cotton swab, or cauterization with silver nitrate; if unsuccessful, OR"},{"t":"Hysteroscopy bleeding: packing of the vaginal vault"},{"t":"Retained products of conception: dilatation and curettage, or medical management with misoprostol ; postabortal endometritis: antibiotics","fl":[{"k":"note","v":"dose not given in the book"}]},{"t":"Vesicovaginal fistula (cotton tampon in the vagina and methylene blue instilled through a urinary catheter; tampon should stain within 20 minutes): Foley catheter"},{"t":"Rh0 immunoglobulin 300 μg IM","if":"Rh-negative after spontaneous or induced abortion"}],"Co":[{"t":"Gynecologic consultation"}]},"name":"Post-procedure bleeding (conization, hysteroscopy, induced abortion) and vesicovaginal fistula","level":"II","imp":"Postprocedure vaginal bleeding / vesicovaginal fistula","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۳۲ ساله ۱۰ روز پس از کونیزاسیون با خونریزی شدید واژینال.","why":"دید مستقیم محل خونریزی و اقدام موضعی؛ شکست: اتاق عمل."},{"id":"gynproc-ohss-postembolization","o":{"L":[{"t":"CBC, electrolytes, liver enzymes, coagulation studies, type and crossmatch (OHSS)"}],"S":[{"t":"IV volume replacement (OHSS)","fl":[{"k":"ci","v":"avoid bimanual pelvic examination to prevent rupturing the ovaries"}]}],"T":[{"t":"Postembolization syndrome: pain control; evaluate for other causes of fever","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Gynecology for admission (OHSS); admission for inadequate pain control or infection (postembolization)"}]},"name":"Ovarian hyperstimulation syndrome / postembolization syndrome","level":"II","imp":"Complication of assisted reproduction or fibroid embolization","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","sc":"زنی ۳۴ ساله پس از IVF با افزایش وزن سریع، آسیت و الیگوری.","why":"OHSS شدید تهدیدکننده حیات؛ پرهیز از معاینه دوهمی؛ مایع وریدی و بستری."}],"ch":"65","name":"Complications of gynecologic procedures","name_fa":"عوارض اعمال ژنیکولوژیک","cc":["abdominal-pain","fever","vaginal-bleeding"],"keywords":"laparoscopy complication, hysteroscopy, vaginal cuff cellulitis, ureteral injury, vesicovaginal fistula, postconization bleeding, septic pelvic thrombophlebitis, induced abortion, ovarian hyperstimulation, postembolization, عوارض ژنیکولوژی","status":"draft","features":["شایع‌ترین علل مراجعه: درد، تب و خونریزی؛ مشاوره با ژنیکولوگی که پروسیجر را انجام داده","لاپاروسکوپی: آسیب حرارتی روده، سوراخ‌شدگی، خونریزی، آسیب عروق/حالب/مثانه، فتق، دهیسانس؛ درد بیش از انتظار: آسیب روده؛ علائم دیررس (روزها تا هفته‌ها)؛ درد دوطرفه تحتانی، تب، لکوسیتوز، پریتونیت؛ رادیوگرافی: ایلئوس یا هوای آزاد","هیستروسکوپی: سوراخ‌شدگی رحم، خونریزی، اضافه حجم مایع، آمبولی گاز و عفونت؛ پک واژن و مشاوره","سلولیت cuff واژن: پس از هیستروکتومی؛ تب، درد شکم/لگن/کمر، ترشح چرکی؛ تندرنس و ایندوراسیون cuff؛ آبسه روز 10 تا 14","عفونت زخم: تب و درد فزاینده طی 2 هفته؛ اریتم، تندرنس، ایندوراسیون و ترشح","آسیب حالب: پس از هیستروکتومی شکمی؛ درد فلانک، تب، CVAT، هماچوری","فیستول وزیکوواژینال: 10 تا 14 روز بعد؛ ترشح آبکی واژن؛ تأیید: تامپون پنبه‌ای و متیلن‌بلو از طریق کاتتر (رنگ ظرف 20 دقیقه)","خونریزی پس از کونیزاسیون: شایع‌ترین؛ سریع و زیاد؛ تأخیری 1 تا 2 هفته","تروموفلبیت سپتیک لگن: پس از سزارین/هیستروکتومی؛ درد شکم و تب؛ CT/MRI ممکن است منفی باشد","سقط القایی: سوراخ‌شدگی رحم، پارگی سرویکس، باقیمانده محصولات، آندومتریت؛ باقیمانده: خونریزی و درد؛ رحم بزرگ و تندر با os باز","ART: OHSS (نفخ، بزرگی تخمدان، افزایش وزن؛ شدید: آسیت، پلورال افیوژن، ناپایداری، الیگوری، ایجاد انعقادپذیری)، عفونت لگن، خونریزی داخل صفاق، torsion آدنکس؛ معاینه دوهمی را پرهیز کن","سندرم پس از آمبولیزاسیون: درد لگن، تب، لکوسیتوز تا 7 روز"],"ddx":[{"n":"Bowel perforation / thermal injury |","cm":1},{"n":"Ureteral injury |","cm":1},{"n":"Septic pelvic thrombophlebitis |","cm":1},{"n":"Vaginal cuff cellulitis / abscess |"},{"n":"Retained products of conception |"},{"n":"Ovarian hyperstimulation syndrome |"}],"redflags":["درد بیش از انتظار، پریتونیت، تب، خونریزی شدید، ناپایداری"],"guide":"ارزیابی متمرکز شامل اسپکولوم استریل و دوهمی؛ مشاوره با ژنیکولوگ.\n- cuff: آنتی‌بیوتیک وسیع‌الطیف (imipenem-cilastatin، یا gentamicin و clindamycin، یا ciprofloxacin + metronidazole)؛ بستری و درناژ توسط رادیولوژی مداخله‌ای.\n- زخم: درناژ و آنتی‌بیوتیک علیه MRSA و استرپتوکوک؛ تهاجمی بستری.\n- حالب: UA و CT با کنتراست یا IVP؛ بستری برای کاتتر حالب و ترمیم (یا نفروستومی پوستی).\n- فیستول: Foley و مشاوره فوری ژنیکولوژی.\n- پس از کونیزاسیون: دید مستقیم؛ Monsel's solution، فشار 5 دقیقه با سواب بزرگ یا cautery نیترات نقره؛ شکست: اتاق عمل.\n- SPT: بستری برای ضدانعقاد و آنتی‌بیوتیک وریدی.\n- سقط القایی: باقیمانده: سونوگرافی لگن؛ D&C یا misoprostol؛ آندومتریت: آنتی‌بیوتیک؛ Rh منفی: Rh0 immunoglobulin 300 μg IM.\n- OHSS: CBC، الکترولیت، آنزیم کبدی، انعقاد، type and crossmatch؛ جایگزینی حجم وریدی و مشاوره ژنیکولوژی برای بستری.\n- postembolization: بررسی علل دیگر تب و کنترل درد؛ بستری در درد کنترل‌نشده یا عفونت.","section":"gynecology-obstetrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 65: Complications of Gynecologic Procedures, pp. 350–352"}});
